        const targets = await Promise.all(['success', 'failure', 'criticalFailure'].map(degree => ctx.actor(`dread ${degree}`)));
        await ctx.cast(dread, await Promise.all(targets.map(t => ctx.token(t))), ['success', 'failure', 'criticalFailure']);
        const frightened = targets.map(t => t.getCondition('frightened')?.value ?? 0);
        assert(JSON.stringify(frightened) === '[0,1,2]', `Success unaffected, failure Frightened 1, critical failure Frightened 2: ${frightened}`);
        // The Queen's Rainbow: a 60-foot line; entering it calls for the save.
