        await combat.createEmbeddedDocuments('Combatant', [casterToken, tStrong, tTied].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
        await combat.startCombat(); await wait(600);
        const plan = await ctx.api.compile(hex.spell);
        assert(ctx.api.saves.supports(plan), 'Jealous Hex: executable');
        const {card} = await ctx.api.saves.start(hex.spell, {sourceActor: hex.caster, plan, targets: [tStrong, tTied], castRank: 1, dc: 24, skipConfirmation: true});
        const s0 = ctx.state(card);
        const strongT = s0.targets.find(t => t.actorUuid === strong.uuid), tiedT = s0.targets.find(t => t.actorUuid === tied.uuid);
        const choice = {strong: strongT.attributeCondition, tied: tiedT.attributeCondition};
        await ctx.api.saves.rollSave(card, strongT.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, strongT.id, {action: 'degree', degree: 'criticalFailure'});
        await ctx.api.saves.rollSave(card, tiedT.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, tiedT.id, {action: 'degree', degree: 'failure'});
        let refused = false; try { await ctx.api.saves.finalize(card); } catch (error) { refused = true; }
        await ctx.api.saves.correctTarget(card, tiedT.id, {action: 'attribute-condition', degree: 'drained'});
        await ctx.api.saves.finalize(card); await wait(1500);
        const conds = actor => ['enfeebled', 'clumsy', 'drained', 'stupefied'].map(slug => [slug, actor.getCondition(slug)?.value ?? 0]).filter(([, v]) => v).map(([slug, v]) => `${slug} ${v}`);
        const applied = {strong: conds(strong), tied: conds(tied)};
        const castId = ctx.state(card).castId, record = () => ctx.api.ongoing.records().find(r => r.castId === castId);
        // Around to the caster's next turn: a Will save for each hexed creature; the strong one succeeds and is freed.
