        await combat.nextTurn(); await wait(400); await ctx.api.ongoing.reconcile({clockEvent: true});
        await combat.nextTurn(); await wait(800); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(1500);
        const obligations = record()?.obligations.filter(o => o.kind === 'recurring-save' && o.cardId) ?? [];
        for (const o of obligations) {
            const c = game.messages.get(o.cardId), t = ctx.state(c).targets[0];
            await ctx.api.saves.rollSave(c, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(c, t.id, {action: 'degree', degree: t.actorUuid === strong.uuid ? 'success' : 'failure'});
            await ctx.api.saves.finalize(c); await wait(1200);
        }
        await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(800);
        out.jealousHex = {choice, refusedBeforeTieChoice: refused, applied, obligations: obligations.map(o => o.label), after: {strong: conds(strong), tied: conds(tied)}};
        await combat.delete();
