    // Rank 5 batch 54: Mirror Malefactors at 5th — the target fails at the cast (7d8 mental) and is Frightened 1, which a decrease can't lower; on the Sustain it
    // critically succeeds: the spell ends and the Frightened goes with it.
    async rank5Batch54(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
        const g = canvas.grid.size;
        const out = {};
        let combat = null;
        try {
            const fixture = await ctx.setup('Mirror Malefactors');
            const victim = await ctx.actor('mirror target', {level: 5}); await victim.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const tVictim = await place(victim, 25 * g, 1 * g); await wait(500);
            const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
            const plan = await ctx.api.compile(fixture.spell);
            const started = await ctx.api.ongoing.startLingering(fixture.spell, plan, {castRank: 5, targets: [tVictim], dc: 26});
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            const resolve = async (obligation, degree) => {
                await ctx.api.ongoing.request('review-targets', {castId: started.castId, revision: rec().revision, key: obligation.key, affected: true}); await wait(800);
                const card = game.messages.get(rec().obligations.find(o => o.key === `${obligation.key}:save`).cardId), target = ctx.state(card).targets[0];
                await ctx.api.saves.rollSave(card, target.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, target.id, {action: 'degree', degree});
                const before = victim.hitPoints.value;
                await ctx.api.saves.finalize(card); await wait(1200);
                return {formula: ctx.state(card).damage?.formula ?? null, total: ctx.state(card).damage?.total ?? null, lost: before - victim.hitPoints.value};
            };
            out.cast = await resolve(rec().obligations.find(o => o.kind === 'membership' && o.status === 'pending'), 'failure');
            out.frightened = victim.getCondition('frightened')?.value ?? 0;
            await victim.decreaseCondition('frightened').catch(() => {}); await wait(400);
            out.afterDecrease = victim.getCondition('frightened')?.value ?? 0;
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tVictim].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            await ctx.api.ongoing.request('sustain', {castId: started.castId, revision: rec().revision}); await wait(600);
            const sustain = rec().obligations.find(o => o.kind === 'membership' && o.status === 'pending' && o.event === 'sustain');
            out.sustain = sustain ? await resolve(sustain, 'criticalSuccess') : null;
            await wait(800);
            out.status = rec()?.status ?? null;
            out.frightenedAfter = victim.getCondition('frightened')?.value ?? 0;
        } catch (error) { out.error = error.stack ?? error.message; }
        if (combat) await combat.delete();
        assert(!out.error && /^7d8 mental$/.test(out.cast?.formula ?? '') && out.cast.lost === out.cast.total && out.frightened === 1 && out.afterDecrease === 1
            && out.sustain && out.sustain.lost === 0 && out.status === 'ended' && out.frightenedAfter === 0, `Rank 5 batch 54: ${JSON.stringify(out)}`);
        return {batch54: out};
    },
