            const fixture = await ctx.setup('Infectious Comedy');
            const plan = await ctx.api.compile(fixture.spell);
            const first = await ctx.actor('comedy failure', {level: 1}), second = await ctx.actor('comedy critical failure', {level: 1});
            const tFirst = await ctx.token(first), tSecond = await ctx.token(second);
            const before = game.messages.contents.length;
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [tFirst], castRank: 5, skipConfirmation: true});
            let t = ctx.state(card).targets[0];
