                await ctx.api.saves.rollSave(first.card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(first.card, t.id, {action: 'degree', degree: 'failure'});
                await ctx.api.saves.finalize(first.card); await wait(1500);
                out.late = late.hasCondition('fascinated');
                out.lateCards = game.messages.contents.slice(mark).filter(m => m.flags?.['pf2e-automatic-resolution']?.chainSave).length;
