            for (const [i, t] of ctx.state(card).targets.entries()) {
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: i === 0 ? 'failure' : 'criticalFailure'});
            }
