    // Rank 3 batch 77: Steal Shadow at 4th — one target fails (4d4 void, Enfeebled 1), one succeeds (Enfeebled 1 for 1 round); on the caster's next
    // round the Sustain opens a basic save for the failed target only: a failure takes 4d4 void again.
    async rank3Batch77(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        let combat = null;
        try {
            const fixture = await ctx.setup('Steal Shadow');
            await fixture.caster.update({'system.details.level.value': 7});
            await fixture.spell.update({'system.location.heightenedLevel': 4});
            const foes = [];
            for (const name of ['shadow failure', 'shadow success']) { const a = await ctx.actor(name, {level: 1}); await a.update({'system.attributes.hp.max': 300}); await a.update({'system.attributes.hp.value': 300}); foes.push(a); }
            const tokens = await Promise.all(foes.map(a => ctx.token(a)));
            const tCaster = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [tCaster, ...tokens.map(t => t.document ?? t)].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            const plan = await ctx.api.compile(fixture.spell);
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: tokens, castRank: 4, skipConfirmation: true});
            for (const [i, t] of ctx.state(card).targets.entries()) {
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: i === 0 ? 'failure' : 'success'});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            out.cast = {formula: ctx.state(card).damage?.formula ?? null, total: ctx.state(card).damage?.total ?? null, foes: foes.map(a => ({lost: 300 - a.hitPoints.value, enfeebled: a.getCondition('enfeebled')?.value ?? 0}))};
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === ctx.state(card).castId);
            out.strikeTargets = rec()?.sustainStrike?.targetTokenUuids?.length ?? null;
            for (let i = 0; i < 3; i++) { await combat.nextTurn(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); }
            const before = foes.map(a => a.hitPoints.value);
            await ctx.api.ongoing.request('sustain', {castId: rec().castId, revision: rec().revision}); await wait(1500);
            const strikeCard = game.messages.get((rec().sustainStrikeCards ?? []).at(-1));
            if (strikeCard) {
                const st = ctx.state(strikeCard);
                out.strikeNames = st.targets.map(t => t.name);
                const t = st.targets[0];
                await ctx.api.saves.rollSave(strikeCard, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(strikeCard, t.id, {action: 'degree', degree: 'failure'});
                await ctx.api.saves.finalize(strikeCard); await wait(1500);
                out.strike = {formula: ctx.state(strikeCard).damage?.formula ?? null, total: ctx.state(strikeCard).damage?.total ?? null, lost: foes.map((a, i) => before[i] - a.hitPoints.value)};
            }
            await ctx.api.ongoing.request('end', {castId: rec().castId}); await wait(800);
            out.afterEnd = foes[0].getCondition('enfeebled')?.value ?? 0;
        } catch (error) { out.error = error.stack ?? error.message; }
        if (combat) await combat.delete();
        const c = out.cast ?? {}, k = out.strike ?? {};
        assert(!out.error && /^4d4 void$/.test(c.formula ?? '') && c.foes?.[0].lost === c.total && c.foes[0].enfeebled === 1 && c.foes[1].lost === 0 && c.foes[1].enfeebled === 1
            && out.strikeTargets === 1 && out.strikeNames?.length === 1 && /shadow failure$/.test(out.strikeNames[0]) && /^4d4 void$/.test(k.formula ?? '') && k.lost?.[0] === k.total && k.lost[1] === 0
            && out.afterEnd === 0, `Rank 3 batch 77: ${JSON.stringify(out)}`);
        return {batch77r3: out};
    },
    // Rank 5 batch 59: Steal the Sky at 6th — a failure that hit a surface (GM: yes): 40 bludgeoning, Prone and the grounding note; a critical failure that didn't
