            await pending?.update({[`flags.${NS}.pendingSpellshape.choice`]: foes[0].uuid});
            const m2 = await castNow('Fear', 1);
            await card(m2, 'Fear', 1, ['failure', 'failure']);
            out.bleeding = [bleed(foes[0]), bleed(foes[1])]; await reset();
            // Trepidation Spell on Phantom Pain at 1 (a Will save, no fear of its own): Frightened 2 on a critical failure.
            await arm('Trepidation Spell'); const m3 = await castNow('Phantom Pain', 1);
            const s3 = await card(m3, 'Phantom Pain', 1, ['criticalFailure'], [tokens[0]]);
            out.trepidation = {frightened: foes[0].getCondition('frightened')?.value ?? 0, riders: JSON.stringify(s3.targets[0]?.shapeResults ?? s3.targets[0]?.riderResults ?? null).slice(0, 300)}; await reset();
            // ... and refused on Fear at 6 (only 1 below the highest, 7).
            await arm('Trepidation Spell'); const m3b = await castNow('Fear', 6);
            out.trepidationHigh = (m3b?.getFlag(NS, 'shaping')?.shapes ?? []).map(sh => sh.unmet);
            // Heightened Spell on Fireball at 3.
