        const until = async find => { for (let i = 0; i < 40; i++) { const found = find(); if (found) return found; await wait(300); } return null; };
        const find = async (trait, level) => { for (const pack of game.packs.filter(p => p.documentName === 'Actor')) { const index = await pack.getIndex({fields: ['system.details.level.value', 'system.traits.value', 'system.traits.rarity']});
            const hit = index.find(e => e.type === 'npc' && e.system?.traits?.value?.includes(trait) && e.system?.details?.level?.value === level && (e.system?.traits?.rarity ?? 'common') === 'common'); if (hit) return hit.uuid; } return null; };
