            const spells = await Promise.all(['Fireball', 'Summon Animal'].map(name => fromPack('pf2e.spells-srd', name).then(o => { o.system.location = {value: entries[0].id}; return o; })));
            const gear = await Promise.all(['Power Ring (Silver)', 'Precision', 'Calling'].map(name => fromPack('pf2e-team-plus-magic.items', name)));
            const made = await caster.createEmbeddedDocuments('Item', [...spells, ...gear]);
            await made.find(i => i.name === 'Power Ring (Silver)').update({'system.equipped.carryType': 'worn', 'system.equipped.invested': true});
            const spell = name => made.find(i => i.type === 'spell' && i.name === name);
            const foes = [];
            for (const n of ['tpf8 one', 'tpf8 two']) { const f = await ctx.actor(n, {level: 1}); await f.update({'system.attributes.hp.max': 500, 'system.attributes.ac.value': 5}); await f.update({'system.attributes.hp.value': 500}); foes.push(f); }
            const tCaster = await place(caster, 2 * g, 2 * g), tFoes = [await place(foes[0], 4 * g, 2 * g), await place(foes[1], 5 * g, 2 * g)]; await wait(1500);
            const arm = async (name, choice = null) => { await made.find(i => i.name === name && i.type !== 'spell').toMessage(); await wait(1200);
                if (choice) { const pending = caster.itemTypes.effect.find(e => e.flags?.[NS]?.pendingSpellshape); await pending?.update({[`flags.${NS}.pendingSpellshape.choice`]: choice}); } };
            const castNow = async (name, rank) => { const mark = game.messages.size; const sp = spell(name); await sp.spellcasting.cast(sp, {rank, consume: false}); return until(() => game.messages.contents.slice(mark).find(m => m.flags?.pf2e?.casting && m.actor === caster && m.getFlag(NS, 'shaping'))); };
            const shaped = message => (message?.getFlag(NS, 'shaping')?.shapes ?? []).map(sh => [sh.name, sh.read, sh.unmet]);
            // Hone Spell on Fireball at 3.
            await arm('Precision', foes[0].uuid); const m1 = await castNow('Fireball', 3);
            const r1 = await ctx.api.saves.start(spell('Fireball'), {plan: await ctx.api.compile(spell('Fireball')), sourceActor: caster, targets: tFoes, castRank: 3, skipConfirmation: true, sourceMessageId: m1.id});
            const c1 = r1.card ?? r1;
            const one = ctx.state(c1).targets.find(t => !t.excluded);
            const mark = game.messages.size;
            await ctx.api.saves.rollSave(c1, one.id, {skipDialog: true}); await wait(800);
            const attack = game.messages.contents.slice(mark).find(m => m.flags?.pf2e?.context?.type === 'attack-roll');
            const degree = ctx.state(c1).targets.find(t => t.id === one.id).degree;
            await ctx.api.saves.finalize(c1); await wait(2000);
            out.hone = {shapes: shaped(m1), excluded: ctx.state(c1).targets.filter(t => t.excluded).map(t => t.name), attackOutcome: attack?.flags?.pf2e?.context?.outcome ?? null, degree,
                ring: (attack?.flags?.pf2e?.modifiers ?? []).filter(mod => /power ring/.test(mod.label ?? '')).map(mod => `${mod.type} ${mod.modifier}`), lost: foes.map(f => 500 - f.hitPoints.value), total: ctx.state(c1).damage?.total ?? null};
