            out.song = {shapes: shaped(m2), rules: caster.itemTypes.effect.filter(e => /Song of Strength/.test(e.name)).flatMap(e => e.system.rules.filter(r => r.key === 'FlatModifier').map(r => `${[r.selector].flat().join('/')} ${r.value}`))};
