            await caster.update({'system.attributes.hp.value': 200});
            await caster.createEmbeddedDocuments('Item', [{name: 'arcane spontaneous', type: 'spellcastingEntry', system: {tradition: {value: 'arcane'}, prepared: {value: 'spontaneous'}, spelldc: {dc: 28, value: 18}, proficiency: {value: 2}, slots: {slot1: {value: 3, max: 3}}}},
                {name: 'magus focus', type: 'spellcastingEntry', system: {tradition: {value: 'arcane'}, prepared: {value: 'focus'}, spelldc: {dc: 28, value: 18}, proficiency: {value: 2}}}]);
            const entry = caster.itemTypes.spellcastingEntry.find(e => e.name === 'arcane spontaneous'), focus = caster.itemTypes.spellcastingEntry.find(e => e.name === 'magus focus');
            const ignition = await fromPack('pf2e.spells-srd', 'Ignition'); ignition.system.location = {value: entry.id};
            const fear = await fromPack('pf2e.spells-srd', 'Fear'); fear.system.location = {value: entry.id};
            const havok = await fromPack('magus.magus-focus-spells', 'Wreak Havok'); havok.system.location = {value: focus.id};
            await caster.createEmbeddedDocuments('Item', [ignition, fear, havok, await fromPack('magus.magus-actions', 'Arcane Cascade+', 'action'), await fromPack('magus.magus-feats', 'Reservoir of Power'), await fromPack('magus.magus-actions', 'Arcane Cascade: Puppet String')]);
            await caster.update({'system.resources.focus': {value: 1, max: 1}});
            await canvas.scene.createEmbeddedDocuments('Token', [{...caster.prototypeToken.toObject(), actorId: caster.id, actorLink: true, x: 8 * g, y: 5 * g}]);
            const foe = await ctx.actor('tpf25 foe', {level: 1, save: -20}); const [foeToken] = await canvas.scene.createEmbeddedDocuments('Token', [{...foe.prototypeToken.toObject(), actorId: foe.id, actorLink: true, x: 10 * g, y: 5 * g}]);
            await wait(800);
            canvas.tokens.setTargets([foeToken.id]); await wait(300);
            const cast = async (name, rank) => { const spell = caster.itemTypes.spell.find(i => i.name === name); const mark = game.messages.size; await spell.spellcasting.cast(spell, {rank, consume: false}); const c = await until(() => game.messages.contents.slice(mark).find(m => m.flags?.pf2e?.casting && m.actor === caster)); await wait(1500); return c; };
            const stanceFrom = async uuid => { const t = await fromUuid(uuid); const o = t.toObject(); delete o._id; foundry.utils.setProperty(o, '_stats.compendiumSource', uuid); const [made] = await caster.createEmbeddedDocuments('Item', [o]); await wait(400); return made; };
            const selection = effect => effect?.flags?.pf2e?.rulesSelections?.stanceArcaneCascade ?? effect?.flags?.system?.rulesSelections?.stanceArcaneCascade ?? effect?.system?.rules?.find(r => r.flag === 'stanceArcaneCascade')?.selection ?? null;
            // The stance's type: Magus+'s after Ignition, PF2e's after Fear.
            await cast('Ignition', 1);
            const plus = await stanceFrom('Compendium.magus.magus-effects.Item.js9M8VQ6sH1R6Fq1');
            out.plusAfterIgnition = selection(plus); await plus?.delete();
            await cast('Fear', 1);
            const official = await stanceFrom('Compendium.pf2e.feat-effects.Item.fsjO5oTKttsbpaKl');
            out.officialAfterFear = selection(official); await official?.delete();
