            const caster = await Actor.create({name: 'PFTEST P23 Affliction tpf24 magus', type: 'character', flags: {[NS]: {phase23AfflictionFixture: true}}});
            await caster.update({'system.details.alliance': 'party', 'system.details.level.value': 10});
