            const feats = [await fromPack('magus.magus-feats', 'Whirling Wand Strike'), await fromPack('magus.magus-feats', 'Eat This!'), await fromPack('magus.magus-feats', 'Dealer of Death'), await fromPack('magus.magus-feats', 'Slide Slice'), await fromPack('magus.magus-feats', 'Living Grimoire')];
            await caster.createEmbeddedDocuments('Item', [ignition, sword, deck, wand, ...feats, {name: 'PFTEST Arcane Cascade', type: 'effect', system: {slug: 'arcane-cascade', rules: [], duration: {value: -1, unit: 'unlimited', expiry: null, sustained: false}}}]);
