            const [entry] = await caster.createEmbeddedDocuments('Item', [{name: 'arcane spontaneous', type: 'spellcastingEntry', system: {tradition: {value: 'arcane'}, prepared: {value: 'spontaneous'}, spelldc: {dc: 28, value: 18}, proficiency: {value: 2}, slots: {slot1: {value: 3, max: 3}, slot3: {value: 2, max: 2}}}}]);
            const ignition = await fromPack('pf2e.spells-srd', 'Ignition'); ignition.system.location = {value: entry.id};
