            const mark = game.messages.size; await spell.spellcasting.cast(spell, {rank: 10, consume: false});
            const cast = await until(() => game.messages.contents.slice(mark).find(m => m.flags?.pf2e?.casting && m.actor === caster)); await wait(800);
            const r = await ctx.api.execute(spell, {sourceActor: caster, plan: await ctx.api.compile(spell), targets: [], castRank: 10, summonUuid: animal, skipConfirmation: true, sourceMessageId: cast?.id}); await wait(2500);
            summoned = r?.actorUuid ? await fromUuid(r.actorUuid) : null; summonEffect = r?.effectUuid ? await fromUuid(r.effectUuid) : null;
            const sToken = canvas.scene.tokens.find(t => t.actorId === summoned?.id);
            const speedBefore = Number((await fromUuid(animal))?.system?.attributes?.speed?.value ?? (await fromUuid(animal))?.system?.movement?.speeds?.land?.value ?? NaN);
            out.colossal = {name: summoned?.name ?? null, size: summoned?.size ?? null, token: sToken ? [sToken.width, sToken.height] : null, land: summoned?.system?.movement?.speeds?.land?.value ?? summoned?.attributes?.speed?.total ?? null, speedBefore,
                trample: summoned?.itemTypes.action.some(a => a.name === 'Trample') ?? false, trampleDice: summoned?.itemTypes.effect.some(e => /Trample's damage dice/.test(e.name)) ?? false,
                shatterer: summoned?.itemTypes.action.some(a => a.name === 'Earth-Shatterer') ?? false, region: canvas.scene.regions.some(rg => /Megalophobia/.test(rg.name)),
                ongoing: summonEffect?.flags?.[NS]?.summon?.ongoingCastIds?.length ?? 0};
