            let m0 = game.messages.size; await shatter.toMessage(); await wait(2000);
            out.quake = !!game.messages.contents.slice(m0).find(m => m.flags?.pf2e?.casting && m.actor === summoned && /Earthquake/.test(m.item?.name ?? m.flavor ?? m.content));
            m0 = game.messages.size; await shatter.toMessage(); await wait(1500);
            out.quakeAgain = game.messages.contents.slice(m0).some(m => /used within the last minute/.test(m.content));
