            await combat.createEmbeddedDocuments('Combatant', [casterToken, foeToken].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 5})));
            await combat.startCombat(); await wait(800); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(800);
            await combat.nextTurn(); await wait(800); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(2500);
            out.megalophobia = {frightened: foe.getCondition('frightened')?.value ?? null, fleeing: foe.hasCondition('fleeing'), immune: foe.itemTypes.effect.some(e => /Temporary immunity/.test(e.name))};
            // Colossal Aspect Form: Animal Shift at 10 — the form Gargantuan with reach 25, the token 6 by 6, the module's Trample; all undone as the form ends.
            const shifter = await Actor.create({name: 'PFTEST P23 Affliction tpf20 shifter', type: 'character', flags: {[NS]: {phase23AfflictionFixture: true}}});
            await shifter.update({'system.details.alliance': 'party', 'system.details.level.value': 20});
            const [entry2] = await shifter.createEmbeddedDocuments('Item', [{name: 'primal spontaneous', type: 'spellcastingEntry', system: {tradition: {value: 'primal'}, prepared: {value: 'spontaneous'}, spelldc: {dc: 40, value: 30}, proficiency: {value: 3}, slots: {slot10: {value: 1, max: 1}}}}]);
