        const c = out.colossal ?? {}, mg = out.megalophobia ?? {};
        assert(!out.error && c.size === 'grg' && JSON.stringify(c.token) === '[6,6]' && c.land === c.speedBefore + 20 && (c.trample || c.trampleDice) && c.shatterer && c.region && c.ongoing === 1
            && out.quake && out.quakeAgain && mg.frightened >= 2 && mg.immune && out.ended.regions === 0 && out.ended.summon === false
            && out.aspectForm?.shift?.size === 'grg' && out.aspectForm.shift.reach === 25 && out.aspectForm.size === 'grg' && JSON.stringify(out.aspectForm.token) === '[6,6]' && out.aspectForm.trample
            && JSON.stringify(out.aspectForm.after.token) === '[1,1]' && !out.aspectForm.after.trample, `Third-party features batch 20: ${JSON.stringify(out)}`);
