            const tvFoe = await place(vFoe, 30 * g, 8 * g), tvAlly = await place(vAlly, 32 * g, 8 * g); await wait(3000);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [tCaster, tvFoe].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            const {card: vCard} = await ctx.api.saves.start(visage, {sourceActor: caster, plan: await ctx.api.compile(visage), targets: [tvFoe.object ?? tvFoe], castRank: 3, skipConfirmation: true});
            const vt = ctx.state(vCard).targets[0];
            await ctx.api.saves.rollSave(vCard, vt.id, {skipDialog: true}); await ctx.api.saves.correctTarget(vCard, vt.id, {action: 'degree', degree: 'failure'});
            await ctx.api.saves.finalize(vCard); await wait(1500);
