            out.visageDebug = {distance: tokenDistance(tvFoe, tvAlly)};
            await ctx.api.ongoing.request('sustain', {castId, revision: rec().revision, allyTokenUuids: [tvAlly.uuid]}); await wait(1500);
            out.visageDebug.after = {sustainedRound: rec()?.sustainedRound ?? null, cards: rec()?.sustainAllyCards ?? null, status: rec()?.status ?? null, review: rec()?.review ?? rec()?.reviewReason ?? null};
