            const caster = await ctx.actor('tp22 caster', {level: 5}); await caster.update({'system.details.alliance': 'party', 'system.attributes.hp.temp': 0});
            const [entry] = await caster.createEmbeddedDocuments('Item', [{name: 'innate', type: 'spellcastingEntry', system: {tradition: {value: 'arcane'}, prepared: {value: 'innate'}, spelldc: {dc: 24, value: 14}}}]);
            const pack = await game.packs.get('pf2e-team-plus-magic.items').getDocuments();
            const add = async name => { const source = pack.find(d => d.name === name && d.system.description.value).toObject(); delete source._id; source.system.location = {value: entry.id}; return (await caster.createEmbeddedDocuments('Item', [source]))[0]; };
            const ignition = await add('Dynamic Ignition'), feast = await add('Dynamic Vampiric Feast');
