            const card1 = game.messages.contents.filter(m => m.flags?.[NSX]?.incarnate?.spellName === 'Dynamic Ignition').at(-1);
            const [zone] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST ignition square', flags: {pf2e: {messageId: card1.id}}, shapes: [{type: 'rectangle', x: 30 * g, y: 30 * g, width: g, height: g, rotation: 0, hole: false}]}]); regions.push(zone);
            const r1 = await ctx.api.incarnatePhase(card1, 'square', {region: zone}); await wait(1200);
