            const t2 = ctx.state(c2).targets[0];
            await ctx.api.saves.rollSave(c2, t2.id, {skipDialog: true, attackNumber: 1}); await ctx.api.saves.correctTarget(c2, t2.id, {action: 'degree', degree: 'criticalSuccess'});
            await ctx.api.saves.finalize(c2); await wait(1800);
            out.critical = {total: ctx.state(c2).damage?.total ?? null, lost: 100 - f2.actor.system.attributes.hp.value, persistent: f2.actor.itemTypes.condition.filter(c => c.slug === 'persistent-damage').map(c => c.system.persistent.damageType)};
            // Vampiric Feast, one action: the marker; then Ignition's hit (the caster's next damaging spell).
            const fv1 = feast.loadVariant({overlayIds: ['BRyUBBt1yBBwYp2r']});
            await ctx.api.execute(fv1, {sourceActor: caster, plan: await ctx.api.compile(fv1), targets: [], castRank: 3, skipConfirmation: true}); await wait(1200);
            const marked = caster.itemTypes.effect.some(e => e.flags?.[NSX]?.runtime?.vampiricNext);
            const f3 = await foe('tp22 marked foe');
            const {card: c3} = await ctx.api.saves.start(v2, {plan: await ctx.api.compile(v2), sourceActor: caster, targets: [f3.token.object ?? f3.token], castRank: 3, skipConfirmation: true});
            const t3 = ctx.state(c3).targets[0];
