            await ctx.api.saves.finalize(c3); await wait(2000);
            const lost3 = 100 - f3.actor.system.attributes.hp.value;
            out.marker = {marked, lost: lost3, temp: caster.system.attributes.hp.temp, markerGone: !caster.itemTypes.effect.some(e => e.flags?.[NSX]?.runtime?.vampiricNext)};
            // Vampiric Feast, two actions, a failure.
