            await caster.update({'system.attributes.hp.temp': 0}); await wait(500);
            const f4 = await foe('tp22 feast foe');
            const fv2 = feast.loadVariant({overlayIds: ['q9m3w4jgjMYkZ8SK']});
            const {card: c4} = await ctx.api.saves.start(fv2, {plan: await ctx.api.compile(fv2), sourceActor: caster, targets: [f4.token.object ?? f4.token], castRank: 3, skipConfirmation: true});
            const t4 = ctx.state(c4).targets[0];
            await ctx.api.saves.rollSave(c4, t4.id, {skipDialog: true}); await ctx.api.saves.correctTarget(c4, t4.id, {action: 'degree', degree: 'failure'});
            await ctx.api.saves.finalize(c4); await wait(2000);
