            const mark = game.messages.size;
            const fearSpell = caster.itemTypes.spell.find(s => s.name === 'Fear');
            target(tFoe);
            await fearSpell.spellcasting.cast(fearSpell, {rank: 1, consume: false});
            const storeCard = await until(() => game.messages.contents.slice(mark).find(m => m.flags?.[NSX]?.reservoir && !m.flags[NSX].reservoir.release));
            const fearCast = game.messages.contents.slice(mark).find(m => m.flags?.pf2e?.casting && m.item?.name === 'Fear');
            if (storeCard) await api.reservoir(storeCard, 'store');
            out.reservoir = {card: !!storeCard, stored: caster.getFlag(NSX, `spellReservoir.${longsword.id}`)?.name ?? null, lost: fearCast?.getFlag(NSX, 'spellLost')?.reason ?? null};
            const mark2 = game.messages.size;
            const action = caster.system.actions.find(a => a.item?.id === longsword.id);
            await action.variants[0].roll({event: new MouseEvent('click', {shiftKey: true})});
