        const entries = await caster.createEmbeddedDocuments('Item', ['arcane', 'occult', 'primal', 'divine'].map(tradition => ({name: `${tradition} prepared`, type: 'spellcastingEntry', system: {tradition: {value: tradition}, prepared: {value: 'prepared'}, spelldc: {dc: 30, value: 20}, proficiency: {value: 1}}})));
        const entry = tradition => entries.find(e => e.name === `${tradition} prepared`).id;
