        const entries = await caster.createEmbeddedDocuments('Item', ['arcane', 'divine', 'occult', 'primal'].map(tradition => ({name: `${tradition} prepared`, type: 'spellcastingEntry', system: {tradition: {value: tradition}, prepared: {value: 'prepared'}, spelldc: {dc: 30, value: 20}, proficiency: {value: 1}}})));
