            const [entry] = await actor.createEmbeddedDocuments('Item', [{name: 'General rules casting', type: 'spellcastingEntry', system: {tradition: {value: 'arcane'}, prepared: {value: 'innate'}, spelldc: {dc: 40, value: 30}}}]);
            const sources = [];
