            const card = game.messages.contents.filter(m => m.flags?.[NS]?.incarnate?.source === 'controls' && m.flags[NS].incarnate.spellName === 'Metamorphosis').at(-1);
            const first = await ctx.api.incarnatePhase(card, 'form', {formSpellId: monstrosity.id, formRank: 8, choiceSelections: {'monstrosity-form': 'phoenix'}}); await wait(2000);
            out.meta = {holder: shifter.itemTypes.effect.some(e => e.name === 'Spell Effect: Metamorphosis'), first: first?.spell ?? null, form: shifter.itemTypes.effect.some(e => /Monstrosity Form/.test(e.name)),
                temp: shifter.system.attributes.hp.temp, shroud: canvas.scene.regions.some(r => /Monstrosity Form: Shroud of Flame/.test(r.name)), size: shifter.system.traits.size?.value ?? null};
            out.meta.again = await ctx.api.incarnatePhase(card, 'form', {formSpellId: monstrosity.id, formRank: 8}).then(() => 'again', error => error.message);
