            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            const sStart = await ctx.api.ongoing.startLingering(song.spell, await ctx.api.compile(song.spell), {castRank: 9, dc: 30, targets: [tListener, tBroken]}); await wait(800);
            const sRec = () => ctx.api.ongoing.records().find(r => r.castId === sStart.castId);
            const failureTable = {1: [['frightened', 2]], 2: [['confused', null]], 3: [['stupefied', 4]], 4: [['blinded', null]], 5: [['stunned', null], ['stupefied', 1]]};
            out.song = {};
