            out.herald.wrath = {lost: 500 - hFoe.hitPoints.value, reminder: index, countered: counter?.countered ?? null};
            const unsanctified = await ctx.api.execute(herald.spell, {sourceActor: herald.caster, plan: hPlan, castRank: 8, skipConfirmation: true, choice: 'unsanctified'}); await wait(600);
            await ctx.api.incarnatePhase(game.messages.get(unsanctified.messageId), 'arrive', {targets: [tAlly]}); await wait(800);
            out.herald.quickened = ally.hasCondition('quickened');
