            await ctx.api.incarnatePhase(game.messages.get(peaks.messageId), 'depart', {targets: [tWA], skipConfirmation: true}); await wait(1500);
            const fly = wAlly.itemTypes.effect.find(e => /Fly/.test(e.name));
