            const forests = await ctx.api.execute(warden.spell, {sourceActor: warden.caster, plan: wPlan, castRank: 8, skipConfirmation: true, choice: choices.find(k => /forests/.test(k))}); await wait(600);
            await resolve(forests.messageId, 'arrive', [tWF], ['criticalSuccess']);
            let refused = null; try { await ctx.api.incarnatePhase(game.messages.get(forests.messageId), 'arrive', {targets: [tWF], skipConfirmation: true}); } catch (error) { refused = error.message; }
            const other = await ctx.actor('warden foe 2'); const tWF2 = await place(other, 1400, 500);
            const again = await resolve(forests.messageId, 'arrive', [tWF2], ['failure']);
