            const line = await resolve(arcane.messageId, 'arrive', [tD], ['failure'], {casterChoice: 'force'});
            out.legion = {formula: ctx.state(line).damage?.formula ?? null, choice: ctx.state(line).casterChoice?.selected ?? null, lost: 500 - dFoe.hitPoints.value};
            // Unholy Army: the velstracs' chains; the demons' smoke.
