            const uPlan = await ctx.api.compile(army.spell);
            const velstracs = await ctx.api.execute(army.spell, {sourceActor: army.caster, plan: uPlan, castRank: 8, skipConfirmation: true, choice: 'velstracs'}); await wait(600);
            await resolve(velstracs.messageId, 'arrive', [tV], ['failure']);
            const speed = vFoe.itemTypes.effect.find(e => e.flags?.[NSX]?.runtime?.persistentLink?.damageType === 'bleed');
            out.army = {bleed: vFoe.itemTypes.condition.some(c => c.slug === 'persistent-damage' && c.system.persistent?.damageType === 'bleed'), speed: speed?.system.rules?.map(r => [r.selector, r.value]) ?? null};
            const demons = await ctx.api.execute(army.spell, {sourceActor: army.caster, plan: uPlan, castRank: 8, skipConfirmation: true, choice: 'demons'}); await wait(600);
            const [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Unholy Army smoke', shapes: [{type: 'circle', x: 950, y: 950, radius: 200}], color: '#333333'}]);
            regions.push(region);
            const smoke = await ctx.api.incarnatePhase(game.messages.get(demons.messageId), 'arrive', {region}); await wait(1500);
            const record = ctx.api.ongoing.records().find(r => r.castId === smoke?.castId);
