            const [fist] = await medusa.caster.createEmbeddedDocuments('Item', [{name: 'Test Fist', type: 'melee', system: {bonus: {value: 40}, damageRolls: {a: {damage: '1d4', damageType: 'bludgeoning'}}, weaponType: {value: 'melee'}, traits: {value: ['unarmed']}}}]);
            const strike = () => medusa.caster.system.actions.find(action => action.item?.id === fist.id);
            const dplan = await ctx.api.compile(medusa.spell);
