            const dt = ctx.state(dcard).targets[0];
            canvas.tokens.setTargets([token.id]); await wait(300);
            await strike().variants[0].roll({event: shift()}); await wait(900);
            await ctx.api.saves.rollSave(dcard, dt.id, {skipDialog: true});
            out.medusa = {supported: ctx.api.saves.supports(dplan), degree: ctx.state(dcard).targets[0].degree};
            await ctx.api.saves.finalize(dcard); await wait(1500);
