            await combat.createEmbeddedDocuments('Combatant', [{tokenId: token.id ?? token.document?.id, sceneId: canvas.scene.id, actorId: foe.id, initiative: 20}]);
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(400);
