        for (const actor of actors) { await canvas.scene.deleteEmbeddedDocuments('Token', canvas.scene.tokens.filter(t => t.actorId === actor.id).map(t => t.id)); await actor.delete(); }
        const m = out.maze ?? {}, d = out.medusa ?? {};
        assert(!out.error && m.supported && JSON.stringify(m.notes) === '["1 rounds","1 minutes","10 minutes"]' && m.doors
            && d.supported && d.degree === 'criticalSuccess' && d.slowed === 2 && JSON.stringify(d.after) === '["petrified","no card"]', `Rank 8 batch 8: ${JSON.stringify(out)}`);
