                if (i === 2) { await ctx.api.saves.rollSave(scard, t.id, {skipDialog: true, stage: 'secondary'}); await ctx.api.saves.correctTarget(scard, t.id, {action: 'degree', degree: 'failure', stage: 'secondary'}); }
