            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Field of Razors', shapes: [{type: 'circle', x: 12.5 * g, y: 6.5 * g, radius: 4 * g}], color: '#888888'}]);
