            out.kind = plan.resolution.kind; out.formula = result.formula; out.lost = before - walker.hitPoints.value;
            out.terrain = canvas.scene.regions.get(region.id)?.behaviors?.some(b => b.type === 'modifyMovementCost') ?? null;
