            const s = await ctx.setup('Divine Aura');
            const plan = await ctx.api.compile(s.spell);
            const g = canvas.grid.size;
            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const casterToken = canvas.scene.tokens.find(t => t.actorId === s.caster.id); await casterToken.update({x: 5 * g, y: 5 * g}, {animate: false});
            const ally = await ctx.actor('aura ally'), foe = await ctx.actor('aura foe'); actors.push(ally, foe);
            await ally.update({'system.details.alliance': 'party'}); await foe.update({'system.details.alliance': 'opposition'});
            const tAlly = await place(ally, 6 * g, 5 * g), tFoe = await place(foe, 7 * g, 5 * g); await wait(600);
            const before = {ally: ally.armorClass.value, foe: foe.armorClass.value, caster: s.caster.armorClass.value};
            const started = await ctx.api.ongoing.startLingering(s.spell, plan, {castRank: 8, dc: 30}); await wait(1200);
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            const held = actor => actor.itemTypes.effect.find(e => e.getFlag('pf2e-automatic-resolution', 'lingeringMember') === started.castId);
            out.ac = {ally: ally.armorClass.value - before.ally, foe: foe.armorClass.value - before.foe, caster: s.caster.armorClass.value - before.caster, foeHeld: !!held(foe), casterHeld: !!held(s.caster)};
            const effect = held(ally);
