            out.acMods = ally.armorClass.modifiers?.map(m => `${m.label}:${m.modifier}:${m.enabled}:${m.type}`) ?? null;
            await ally.toggleRollOption('all', 'divine-aura-opposed', effect.id, true); await wait(500);
            out.opposedAc = ally.armorClass.value - before.ally;
            await ally.toggleRollOption('all', 'divine-aura-opposed', effect.id, false); await wait(300);
