                const {card} = await ctx.api.saves.start(s.spell, {sourceActor: s.caster, plan, targets: await Promise.all(targets.map(a => ctx.token(a))), castRank: rank, dc: 30, skipConfirmation: true});
                for (const [i, t] of ctx.state(card).targets.entries()) { await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]}); }
                await ctx.api.saves.finalize(card); await wait(1800);
