            const s = await ctx.setup('Entrancing Eyes');
            const plan = await ctx.api.compile(s.spell);
            const g = canvas.grid.size;
            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const casterToken = canvas.scene.tokens.find(t => t.actorId === s.caster.id); await casterToken.update({x: 20 * g, y: 10 * g}, {animate: false});
            const calm = await ctx.actor('eyes calm'), weak = await ctx.actor('eyes weak'), far = await ctx.actor('eyes far'); actors.push(calm, weak, far);
            const tCalm = await place(calm, 21 * g, 10 * g), tWeak = await place(weak, 22 * g, 10 * g), tFar = await place(far, 21 * g, 12 * g); await wait(600);
            const started = await ctx.api.ongoing.startLingering(s.spell, plan, {castRank: 7, dc: 30}); await wait(1200);
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            const pending = () => rec().obligations.filter(o => o.kind === 'membership' && o.status === 'pending');
            const resolve = async (o, degree) => {
                await ctx.api.ongoing.request('review-targets', {castId: started.castId, revision: rec().revision, key: o.key, affected: true}); await wait(800);
                const card = game.messages.get(rec().obligations.find(x => x.key === `${o.key}:save`).cardId), t = ctx.state(card).targets[0];
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
                await ctx.api.saves.finalize(card); await wait(1200);
            };
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tCalm, tWeak].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            await ctx.api.ongoing.request('sustain', {castId: started.castId, revision: rec().revision}); await wait(400);
            for (let i = 0; i < 3; i++) { await combat.nextTurn(); await wait(700); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(700); }
            const first = pending();
            out.firstRound = first.map(o => o.actorUuid === calm.uuid ? 'calm' : o.actorUuid === weak.uuid ? 'weak' : 'other').sort();
            for (const o of first) await resolve(o, o.actorUuid === calm.uuid ? 'criticalSuccess' : 'criticalFailure');
            out.calmImmune = calm.itemTypes.effect.some(e => /immunity/i.test(e.name));
