            const result = await ctx.api.execute(reprisal.spell, {sourceActor: reprisal.caster, plan, castRank: 7, region, skipConfirmation: true}); await wait(1500);
            const rec = ctx.api.ongoing.records().find(r => r.castId === result.castInstanceId);
