            const card = game.messages.contents.findLast(m => /Hero's Defiance/.test((m.flavor ?? '') + m.content) && /Trigger/.test((m.flavor ?? '') + m.content));
            out.hero = {kind: plan.resolution.kind, healed: hero.caster.system.attributes.hp.value - 10, notes: !!card && /Refocus/.test((card.flavor ?? '') + card.content)};
