            await ctx.api.saves.rollSave(departCard.card, dt.id, {skipDialog: true}); await ctx.api.saves.correctTarget(departCard.card, dt.id, {action: 'degree', degree: 'criticalFailure'});
            await ctx.api.saves.finalize(departCard.card); await wait(1500);
            out.tempest = {drained: arriveFoe.getCondition('drained')?.value ?? 0, frightened: departFoe.getCondition('frightened')?.value ?? 0,
                fleeing: departFoe.hasCondition('fleeing') || departFoe.itemTypes.effect.some(e => /Fleeing/.test(e.name))};
            const stampede = await ctx.setup('Summon Stampede');
            const trampled = await mk('stampede victim');
            const sResult = await ctx.api.execute(stampede.spell, {sourceActor: stampede.caster, plan: await ctx.api.compile(stampede.spell), castRank: 7, skipConfirmation: true}); await wait(600);
            const sMessage = game.messages.get(sResult.messageId);
