            // Phantom Orchestra.
            const orchestra = await ctx.setup('Phantom Orchestra');
            const [oRegion] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST orchestra', shapes: [{type: 'circle', x: 20.5 * g, y: 5.5 * g, radius: 2 * g}], color: '#3355aa'}]); regions.push(oRegion);
            const oCast = await ctx.api.ongoing.startLingering(orchestra.spell, await ctx.api.compile(orchestra.spell), {castRank: 6, region: oRegion, dc: 24}); started.push(oCast.castId); await wait(500);
            const oRec = ctx.api.ongoing.records().find(r => r.castId === oCast.castId);
