            out.recastEnded = !(await fromUuid(stolen.effectUuid));
            const stored = await ctx.api.spellStealAttempt(await fromUuid(second.effectUuid), {targets: [tFoe], choice: 'store', counteractDC: -20}); await wait(600);
            out.store = {status: stored.status, how: stored.how, counteract: stored.counteract, name: (await fromUuid(stored.effectUuid))?.name ?? null};
