            for (const a of [holder, other, walker]) { await a.update({'system.attributes.hp.max': 300}); await a.update({'system.attributes.hp.value': 300}); }
            await holder.update({'system.saves.reflex.value': -20});
            const tHolder = await place(holder, 15 * g, 13 * g), tOther = await place(other, 17 * g, 13 * g), tWalker = await place(walker, 20 * g, 13 * g); await wait(800);
            const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
