            await combat.startCombat(); await wait(500);
            const plan = await ctx.api.compile(fixture.spell);
            const cast = await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, castRank: 6, targets: [tHolder], skipConfirmation: true, mode: 'attended', skipDialog: true}); await wait(800);
            out.cast = {degree: cast.degree, seconds: cast.seconds, formula: cast.formula};
            const hp = a => a.hitPoints.value;
            const turn = async () => { await combat.nextTurn(); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(1200); };
            await turn(); // the caster's turn ends
