            const fixture = await ctx.setup('Rallying Banner');
            const bearer = await ctx.actor('banner bearer'), near = await ctx.actor('banner near'), enemy = await ctx.actor('banner enemy');
            for (const a of [bearer, near]) await a.update({'system.details.alliance': 'party'});
            const [tBearer, tNear, tEnemy] = [await place(bearer, 3 * g, 3 * g), await place(near, 6 * g, 3 * g), await place(enemy, 4 * g, 4 * g)]; await wait(3000);
            const plan = await ctx.api.compile(fixture.spell);
            const result = await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, castRank: 5, skipConfirmation: true, targets: [tBearer]}); await wait(1500);
            await ctx.api.ongoing.reconcile(); await wait(1000);
            const inspired = actor => actor.itemTypes.effect.some(e => /Rallying banner$/.test(e.name));
            const bearerNote = actor => actor.itemTypes.effect.some(e => /the banner's bearer/.test(e.name));
            out.cast = {kind: plan.resolution.kind, bearer: inspired(bearer), near: inspired(near), enemy: inspired(enemy), note: bearerNote(bearer)};
            // A Will save against a fear effect for the near ally.
            const fear = await near.saves.will.roll({dc: {value: 10}, skipDialog: true, extraRollOptions: ['item:trait:fear']}); await wait(1200);
            const fearMods = game.messages.contents.at(-1)?.flags?.pf2e?.modifiers ?? [];
            const plain = await near.saves.will.roll({dc: {value: 10}, skipDialog: true}); await wait(1200);
            const plainMods = game.messages.contents.at(-1)?.flags?.pf2e?.modifiers ?? [];
            out.saves = {fear: fearMods.some(m => /Rallying Banner/i.test(m.label ?? '') && m.enabled !== false), plain: plainMods.some(m => /Rallying Banner/i.test(m.label ?? '') && m.enabled !== false)};
            // The near ally steps out to 250 feet (off the scene's 18 squares, so it's moved far along the edge instead): use a different far token.
            const transfer = await ctx.api.ongoing.request('transfer-aura', {castId: result.castInstanceId, tokenUuid: tNear.uuid}); await wait(800);
            await ctx.api.ongoing.reconcile(); await wait(800);
            out.transfer = {status: transfer?.status, bearerNote: bearerNote(bearer), nearNote: bearerNote(near), near: inspired(near)};
            await ctx.api.ongoing.request('end', {castId: result.castInstanceId}); await wait(800);
