            const rec = () => ctx.api.ongoing.records().find(r => r.castId === result.castInstanceId);
            out.cast = {hero: hero.hasCondition('quickened'), friend: friend.hasCondition('quickened')};
            const crit = await ctx.api.ongoing.request('streak-crit', {castId: result.castInstanceId, tokenUuid: tFriend.uuid}); await wait(800);
            out.crit = {result: crit?.status, friend: friend.hasCondition('quickened')};
            let refused = null; try { await ctx.api.ongoing.request('streak-crit', {castId: result.castInstanceId, tokenUuid: tFar.uuid}); } catch (error) { refused = error.message; }
            out.refused = refused;
