        const h = out.hit ?? {};
        assert(!out.error && /8d6 piercing/.test(h.formula ?? '') && h.lost === h.total && h.penalty === -10 && h.duration?.value === 1 && h.duration.unit === 'minutes' && !h.immobilized
            && out.hitEscape?.penalty === false && out.hitEscape.bleed.join() === '4bleed' && out.crit?.penalty && out.crit.immobilized
            && out.critEscape?.penalty === false && out.critEscape.immobilized === false && out.critEscape.bleed.join() === '4bleed', `Rank 3 batch 90: ${JSON.stringify(out)}`);
