            const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
            const ok = await ctx.actor('pressure success'), stuck = await ctx.actor('pressure failure'), deep = await ctx.actor('pressure critical');
            const [tOk, tStuck, tDeep] = [await place(ok, 4 * g, 4 * g), await place(stuck, 5 * g, 4 * g), await place(deep, 4 * g, 5 * g)]; await wait(4500);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Pressure Zone', shapes: [{type: 'circle', x: 5 * g, y: 5 * g, radius: 3 * g}], color: '#99bbcc'}]);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
