            const entry = holder?.entries.find(e => e.status === 'active' && e.actorUuid === deep.uuid && (e.metadata?.conditions ?? []).some(c => c.actionSave));
            const flag = entry?.metadata.conditions.find(c => c.actionSave)?.ruleFlag;
            out.pop = entry ? await ctx.api.ongoing.request('condition-save', {castId: holder.castId, uuid: entry.uuid, ruleFlag: flag, degree: 'success'}) : null; await wait(1000);
            out.popped = look(deep);
