            const variant = fixture.spell.loadVariant({overlayIds: [overlay]});
            const walker = await ctx.actor('tide walker'); await walker.update({'system.attributes.hp.max': 500}); await walker.update({'system.attributes.hp.value': 500});
            const tWalker = await place(walker, 20 * g, 12 * g);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tWalker].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            const rounds = await save(variant, fixture.caster, tWalker, 5, 'piercing');
            const rState = ctx.state(rounds);
