            const [r2] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Weapon Tide 2R', shapes: [{type: 'rectangle', x: 8 * g, y: 4 * g, width: 4 * g, height: 4 * g}], color: '#aa6666'}]);
            regions.push(r2);
            const placed2 = await ctx.api.saves.placeAreaTerrain(game.messages.get(rounds.id), r2);
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === placed2.castInstanceId);
            out.rounds.hazard = rec()?.declaration?.hazardDamage ?? null;
            const hp = () => walker.hitPoints.value;
