            await place(inner, 26 * g, 2 * g); await place(outer, 18 * g, 2 * g); await wait(800);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Fallow Field', shapes: [{type: 'circle', x: 26.5 * g, y: 2.5 * g, radius: 3 * g}], color: '#999933'}]);
            const plan = await ctx.api.compile(fixture.spell);
