                    await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: foes[i][2]});
                    await ctx.api.saves.correctTarget(card, t.id, {action: foes[i][1] === 'yes' ? 'upgrade-yes' : 'upgrade-no'});
