            await foes[0].update({'system.abilities.int.mod': 5}).catch(() => {}); await foes[1].update({'system.abilities.int.mod': -3}).catch(() => {});
            const tokens = await Promise.all(foes.map(a => ctx.token(a)));
            const before = game.messages.contents.length;
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: tokens, castRank: 3, skipConfirmation: true});
            const degrees = ['success', 'failure', 'criticalFailure', 'criticalSuccess'];
