    // Rank 5 batch 44: Wave of Despair at 7th (heightened) — a failure: the Despair note for 1 minute; at the start of its turn its Will save fails: Slowed 1
    // for that turn (gone when the turn ends); next turn it succeeds: no Slowed. A critical failure: Slowed 1 for 1 minute at once.
    async rank5Batch44(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {steps: []};
        let combat = null;
        try {
            const fixture = await ctx.setup('Wave of Despair');
            await fixture.caster.update({'system.details.level.value': 13});
            await fixture.spell.update({'system.location.heightenedLevel': 7});
            const plan = await ctx.api.compile(fixture.spell);
            const foe = await ctx.actor('despair failure', {level: 1}), worst = await ctx.actor('despair critical failure', {level: 1});
            const tFoe = await ctx.token(foe), tWorst = await ctx.token(worst);
            const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tFoe].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [tFoe, tWorst], castRank: 7, skipConfirmation: true});
            const degrees = ['failure', 'criticalFailure'];
            for (const [i, t] of ctx.state(card).targets.entries()) {
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            out.note = foe.itemTypes.effect.filter(e => /Despair/.test(e.name) && !/this turn/.test(e.name)).map(e => `${e.system.duration.value} ${e.system.duration.unit}`);
            out.worst = {slowed: worst.getCondition('slowed')?.value ?? 0, note: worst.itemTypes.effect.some(e => /: Despair/.test(e.name))};
            out.startSlowed = foe.getCondition('slowed')?.value ?? 0;
            const castId = ctx.state(card).castId, record = () => ctx.api.ongoing.records().find(r => r.castId === castId);
            for (const degree of ['failure', 'success']) {
                await combat.nextTurn(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(1500);
                const obligation = record()?.obligations.filter(o => o.kind === 'recurring-save' && o.cardId && o.status === 'collecting').at(-1);
                if (!obligation) { out.steps.push({degree, missing: true}); break; }
                const save = game.messages.get(obligation.cardId), t = ctx.state(save).targets[0];
                await ctx.api.saves.rollSave(save, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(save, t.id, {action: 'degree', degree});
                await ctx.api.saves.finalize(save); await wait(1500);
                const during = foe.getCondition('slowed')?.value ?? 0;
                await combat.nextTurn(); await wait(1200); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(600);
                const turnEffects = foe.itemTypes.effect.filter(e => /this turn/.test(e.name));
                out.steps.push({degree, during, afterTurn: foe.getCondition('slowed')?.value ?? 0, expired: turnEffects.every(e => e.isExpired), turnEffects: turnEffects.length});
            }
        } catch (error) { out.error = error.stack ?? error.message; }
        if (combat) await combat.delete();
        const [f, s] = out.steps;
        assert(!out.error && JSON.stringify(out.note) === '["1 minutes"]' && out.startSlowed === 0 && out.worst?.slowed === 1 && out.worst.note
            && f?.degree === 'failure' && f.during === 1 && (f.afterTurn === 0 || f.expired) && s?.degree === 'success' && s.during === 0, `Rank 5 batch 44: ${JSON.stringify(out)}`);
        return {batch44: out};
    },
