            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: await Promise.all(foes.map(a => ctx.token(a))), castRank: 4, skipConfirmation: true});
            const degrees = ['criticalSuccess', 'success', 'failure', 'criticalFailure'];
