    // Rank 4 batch 66: Unsettling Knowledge — a failure (Occultism −10) Recalls Knowledge and fails: fascination ended, Frightened 2, and after two
    // decreases still Frightened 1; a critical failure (Occultism +30) succeeds: Frightened 3, no floor.
    async rank4Batch66(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup('Unsettling Knowledge');
            const plan = await ctx.api.compile(fixture.spell);
            const slow = await ctx.actor('unsettled failure', {level: 1}), sharp = await ctx.actor('unsettled critical', {level: 1});
            await slow.update({'system.skills.occultism.base': -10}).catch(() => {}); await sharp.update({'system.skills.occultism.base': 30}).catch(() => {});
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(slow), await ctx.token(sharp)], castRank: 4, skipConfirmation: true});
            const degrees = ['failure', 'criticalFailure'];
            for (const [i, t] of ctx.state(card).targets.entries()) {
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            out.fascinated = [slow.hasCondition('fascinated'), sharp.hasCondition('fascinated')];
            const record = ctx.api.ongoing.records().find(r => r.castId === ctx.state(card).castId);
            const recall = async actor => { const e = record?.entries.find(x => x.actorUuid === actor.uuid && x.metadata?.recallEscape);
                return e ? await ctx.api.ongoing.request('recall-escape', {castId: record.castId, uuid: e.uuid, skill: 'occultism'}) : null; };
            out.slow = await recall(slow); await wait(800);
            out.sharp = await recall(sharp); await wait(800);
            out.after = [slow.hasCondition('fascinated'), sharp.hasCondition('fascinated')];
            for (let i = 0; i < 2; i++) { await slow.decreaseCondition('frightened').catch(() => {}); await wait(300); }
            out.floorHeld = slow.getCondition('frightened')?.value ?? 0;
        } catch (error) { out.error = error.stack ?? error.message; }
        assert(!out.error && JSON.stringify(out.fascinated) === '[true,true]' && out.slow?.status === 'failed' && out.slow.frightened === 2 && out.slow.floor
            && out.sharp?.status === 'understood' && out.sharp.frightened === 3 && !out.sharp.floor && JSON.stringify(out.after) === '[false,false]' && out.floorHeld >= 1,
            `Rank 4 batch 66: ${JSON.stringify(out)}`);
        return {batch66: out};
    },
