    // Rank 4 batch 58: Weaponize Secret at 5th — a failure's rune discharged: 9d6 mental; a critical failure: 1d6+1 persistent mental, and the
    // discharge (9d6) ends it.
    async rank4Batch58(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup('Weaponize Secret');
            await fixture.caster.update({'system.details.level.value': 9}); await fixture.spell.update({'system.location.heightenedLevel': 5});
            const plan = await ctx.api.compile(fixture.spell);
            const fail = await ctx.actor('secret failure', {level: 1}), crit = await ctx.actor('secret critical', {level: 1});
            for (const x of [fail, crit]) await x.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(fail), await ctx.token(crit)], castRank: 5, skipConfirmation: true});
            const degrees = ['failure', 'criticalFailure'];
            for (const [i, t] of ctx.state(card).targets.entries()) {
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            const persistent = a => a.itemTypes.condition.filter(c => c.slug === 'persistent-damage').map(c => [c.system.persistent?.damageType, c.system.persistent?.formula]);
            out.before = persistent(crit);
            const record = ctx.api.ongoing.records().find(r => r.castId === ctx.state(card).castId);
            const discharge = async actor => { const e = record?.entries.find(x => x.actorUuid === actor.uuid && x.metadata?.triggeredDamage); const hp = actor.hitPoints.value;
                const result = e ? await ctx.api.ongoing.request('hostile-damage', {castId: record.castId, uuid: e.uuid}) : null; await wait(800);
                return {formula: result?.formula ?? null, lost: hp - actor.hitPoints.value, persistentEnded: result?.persistentEnded ?? null, ended: result?.ended ?? null}; };
            out.fail = await discharge(fail); out.crit = await discharge(crit);
            out.after = persistent(crit);
        } catch (error) { out.error = error.stack ?? error.message; }
        assert(!out.error && out.before?.[0]?.[0] === 'mental' && /1d6/.test(out.before[0][1] ?? '') && /9d6 mental/.test(out.fail?.formula ?? '') && out.fail.lost > 0 && out.fail.ended
            && /9d6/.test(out.crit?.formula ?? '') && out.crit.persistentEnded === 1 && out.after?.length === 0,
            `Rank 4 batch 58: ${JSON.stringify(out)}`);
        return {batch58: out};
    },
