    // Rank 4 batch 56: Dreamer's Call — the caster picks "flee": a failure is Fascinated and Fleeing; then "prone": a critical failure is Fascinated,
    // Prone and has the every-action note.
    async rank4Batch56(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup("Dreamer's Call");
            const plan = await ctx.api.compile(fixture.spell);
            const cast = async (name, pick, degree) => {
                const a = await ctx.actor(name, {level: 1});
                const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(a)], castRank: 4, skipConfirmation: true});
                await ctx.api.saves.chooseCasterOption(card, pick);
                const t = ctx.state(card).targets[0];
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
                await ctx.api.saves.finalize(card); await wait(1500);
                return {fascinated: a.hasCondition('fascinated'), fleeing: a.hasCondition('fleeing'), prone: a.hasCondition('prone'),
                    notes: a.itemTypes.effect.filter(e => /Course of action|Every action/.test(e.name)).map(e => e.name.replace(/^.*: /, ''))};
            };
            out.flee = await cast('dream fleer', 'flee', 'failure');
            out.prone = await cast('dream kneeler', 'prone', 'criticalFailure');
        } catch (error) { out.error = error.stack ?? error.message; }
        const f = out.flee ?? {}, p = out.prone ?? {};
        assert(!out.error && f.fascinated && f.fleeing && !f.prone && f.notes?.length === 0 && p.fascinated && p.prone && !p.fleeing && p.notes?.includes('Every action'),
            `Rank 4 batch 56: ${JSON.stringify(out)}`);
        return {batch56: out};
    },
    // Rank 3 batch 66: Croak Voice at 4th — a success: the massage control (Fortitude +30) ends the spell; a failure: an auditory action deals 3d10
    // mental; a critical failure: double, and no massage control.
    async rank3Batch66(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup('Croak Voice');
            await fixture.caster.update({'system.details.level.value': 7}); await fixture.spell.update({'system.location.heightenedLevel': 4});
            const plan = await ctx.api.compile(fixture.spell);
            const hoarse = await ctx.actor('croak success', {level: 1}), fail = await ctx.actor('croak failure', {level: 1}), crit = await ctx.actor('croak critical', {level: 1});
            for (const x of [hoarse, fail, crit]) await x.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            await hoarse.update({'system.saves.fortitude.value': 30});
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(hoarse), await ctx.token(fail), await ctx.token(crit)], castRank: 4, skipConfirmation: true});
            const degrees = ['success', 'failure', 'criticalFailure'];
            for (const [i, t] of ctx.state(card).targets.entries()) {
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            const record = () => ctx.api.ongoing.records().find(r => r.castId === ctx.state(card).castId);
            const entry = (actor, key) => record()?.entries.find(e => e.actorUuid === actor.uuid && e.metadata?.[key] && e.status === 'active');
            out.controls = [hoarse, fail, crit].map(a => [!!entry(a, 'endSave'), !!entry(a, 'triggeredDamage')]);
            const hit = async actor => { const e = entry(actor, 'triggeredDamage'); const before = actor.hitPoints.value;
                const result = e ? await ctx.api.ongoing.request('hostile-damage', {castId: record().castId, uuid: e.uuid}) : null; await wait(800);
                return {formula: result?.formula ?? null, total: result?.total ?? null, lost: before - actor.hitPoints.value}; };
            out.fail = await hit(fail); out.crit = await hit(crit);
            const massage = entry(hoarse, 'endSave');
            out.massage = massage ? await ctx.api.ongoing.request('end-save', {castId: record().castId, uuid: massage.uuid}) : null; await wait(800);
            out.status = record()?.status ?? null;
        } catch (error) { out.error = error.stack ?? error.message; }
        assert(!out.error && JSON.stringify(out.controls) === JSON.stringify([[true, false], [true, true], [false, true]])
            && /3d10/.test(out.fail?.formula ?? '') && out.fail.lost > 0 && out.crit?.lost > 0 && /2|double/.test(String(out.crit.formula ?? '')) && out.massage?.ended === true,
            `Rank 3 batch 66: ${JSON.stringify(out)}`);
        return {batch66: out};
    },
