    // Rank 5 batch 39: Blister at 6th — the target fails: 2 blisters; a pop (the target and a creature in the cone) — 8d6 acid, the target succeeds
    // (half), the other fails (full); a second pop; a third is refused.
    async rank5Batch39(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup('Blister');
            await fixture.caster.update({'system.details.level.value': 11}); await fixture.spell.update({'system.location.heightenedLevel': 6});
            const plan = await ctx.api.compile(fixture.spell);
            const target = await ctx.actor('blister target', {level: 1}), near = await ctx.actor('blister near', {level: 1});
            for (const x of [target, near]) await x.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const tTarget = await ctx.token(target), tNear = await ctx.token(near);
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [tTarget], castRank: 6, skipConfirmation: true});
            const t = ctx.state(card).targets[0];
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: 'failure'});
            await ctx.api.saves.finalize(card); await wait(1500);
            const popCard = () => game.messages.contents.filter(m => m.flags?.['pf2e-automatic-resolution']?.popSave).at(-1);
            out.left = popCard()?.flags['pf2e-automatic-resolution'].popSave.left;
            const pop = async degrees => {
                const started = await ctx.api.saves.popSave(popCard(), [tTarget, tNear]);
                const second = started.card;
                for (const [i, x] of ctx.state(second).targets.entries()) {
                    await ctx.api.saves.rollSave(second, x.id, {skipDialog: true}); await ctx.api.saves.correctTarget(second, x.id, {action: 'degree', degree: degrees[i]});
                }
                await ctx.api.saves.finalize(second); await wait(1500);
                return ctx.state(second);
            };
            const b1 = [target.hitPoints.value, near.hitPoints.value];
            const first = await pop(['success', 'failure']);
            out.first = {formula: first.damage?.formula ?? null, total: first.damage?.total ?? null, lost: [b1[0] - target.hitPoints.value, b1[1] - near.hitPoints.value]};
            await pop(['failure', 'failure']);
            out.leftAfter = popCard()?.flags['pf2e-automatic-resolution'].popSave.left;
            out.third = await ctx.api.saves.popSave(popCard(), [tTarget, tNear]).then(() => 'allowed', error => String(error.message ?? error));
        } catch (error) { out.error = error.stack ?? error.message; }
        const f = out.first ?? {};
        assert(!out.error && out.left === 2 && /^8d6 acid$/.test(f.formula ?? '') && f.lost?.[0] === Math.floor(f.total / 2) && f.lost[1] === f.total && out.leftAfter === 0 && /No blisters are left/.test(out.third ?? ''),
            `Rank 5 batch 39: ${JSON.stringify(out)}`);
        return {batch39: out};
    },
