            for (const [i, x] of [[0, 10], [1, 20]]) regions.push((await canvas.scene.createEmbeddedDocuments('Region', [{name: `PFTEST Coral ${i}`, shapes: [{type: 'circle', x: x * g, y: 12 * g, radius: 2 * g}], color: '#cc7766'}]))[0]);
