            const tVictim = await place(victim, casterToken.x + g, casterToken.y); await wait(600);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Sanguine Mist', shapes: [{type: 'circle', x: casterToken.x + g, y: casterToken.y + g / 2, radius: 2.5 * g}], color: '#aa3344'}]);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
