            await fixture.caster.update({'system.details.level.value': rank * 2 - 1}); await fixture.spell.update({'system.location.heightenedLevel': rank});
            const victim = await ctx.actor(`${name} victim`); await victim.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const tVictim = await place(victim, 15 * g, 12 * g); await wait(600);
            const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: `PFTEST ${name}`, shapes: [{type: 'circle', x: 15 * g, y: 12.5 * g, radius: 3 * g}], color: '#557733'}]);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tVictim].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            const plan = await ctx.api.compile(fixture.spell);
            const started = await ctx.api.ongoing.startLingering(fixture.spell, plan, {castRank: rank, region, dc: 30});
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            const resolve = async () => {
                const o = rec().obligations.find(o => o.kind === 'membership' && o.status === 'pending' && o.actorUuid === victim.uuid);
                if (!o) return false;
                await ctx.api.ongoing.request('review-targets', {castId: started.castId, revision: rec().revision, key: o.key, affected: true}); await wait(800);
                const card = game.messages.get(rec().obligations.find(x => x.key === `${o.key}:save`).cardId);
                const t = ctx.state(card).targets[0];
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
                await ctx.api.saves.finalize(card); await wait(1500);
                return true;
            };
            if (timing === 'turn-start') { await combat.nextTurn(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(800); }
            out.saved = await resolve();
            out.held = {grabbed: victim.hasCondition('grabbed'), restrained: victim.hasCondition('restrained')};
            if (timing === 'turn-start') { await combat.nextTurn(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); }
            else { await combat.nextTurn(); await wait(500); await ctx.api.ongoing.reconcile({clockEvent: true}); await combat.nextTurn(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); }
