    // Rank 4 batch 43: Tortoise and the Hare — the foe fails: Slowed 1 for 3 rounds; the card grants an ally Quickened for 1 round (not the foe; once);
    // the foe succeeds: Slowed 1 for 1 round and nothing to grant.
    async rank4Batch43(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup('Tortoise and the Hare');
            await fixture.caster.update({'system.details.level.value': 7});
            const plan = await ctx.api.compile(fixture.spell);
            const ally = await ctx.actor('hare ally', {level: 1});
            await ally.update({'system.details.alliance': fixture.caster.system.details.alliance ?? 'party'});
            const allyToken = await ctx.token(ally);
            const cast = async (name, degree) => {
                const foe = await ctx.actor(name, {level: 1});
                await foe.update({'system.details.alliance': 'opposition'});
                const foeToken = await ctx.token(foe);
                const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [foeToken], castRank: 4, skipConfirmation: true});
                const [t] = ctx.state(card).targets;
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
                await ctx.api.saves.finalize(card); await wait(1200);
                const toFoe = await ctx.api.saves.grantPartner(game.messages.get(card.id), [foeToken]).then(() => 'allowed').catch(error => error.message);
                const granted = await ctx.api.saves.grantPartner(game.messages.get(card.id), [allyToken]).then(r => r.status).catch(error => error.message);
                await wait(800);
                const again = await ctx.api.saves.grantPartner(game.messages.get(card.id), [allyToken]).then(() => 'allowed').catch(error => /already granted/.test(error.message) ? 'refused' : error.message);
                return {slowed: foe.getCondition('slowed')?.value ?? 0, slowedFor: foe.itemTypes.effect.find(e => /Slowed/.test(e.name))?.system.duration ?? null, toFoe, granted, again,
                    quickened: ally.hasCondition('quickened'), note: ally.itemTypes.effect.some(e => /extra action/.test(e.name))};
            };
            out.failure = await cast('tortoise fail', 'failure');
            for (const e of ally.itemTypes.effect.filter(e => /Tortoise/.test(e.name))) await e.delete(); await wait(300);
            out.success = await cast('tortoise success', 'success');
        } catch (error) { out.error = error.stack ?? error.message; }
        const f = out.failure ?? {}, s = out.success ?? {};
        assert(!out.error && f.slowed === 1 && /can't be the foe/.test(f.toFoe) && f.granted === 'granted' && f.again === 'refused' && f.quickened && f.note
            && s.slowed === 1 && /grants the other target nothing/.test(s.granted) && !s.quickened, `Rank 4 batch 43: ${JSON.stringify(out)}`);
        return {batch43: out};
    },
    // Rank 3 batch 57: Spirit Veil — at 3rd the caster is Concealed with the note; at 5th two allies too; three allies are refused.
