        assert(!out.error && out.base?.concealed && out.base.note && out.tooMany === 'refused' && h.caster?.concealed && h.allies?.[0]?.concealed && h.allies[0].note
            && h.allies[1]?.concealed && !h.allies[2]?.concealed, `Rank 3 batch 57: ${JSON.stringify(out)}`);
        return {batch57: out};
