            await foe.update({'system.attributes.hp.value': 200, 'system.attributes.hp.max': 200});
            const tFoe = await ctx.token(foe);
            const result = await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, targets: [], castRank: 7, skipConfirmation: true}); await wait(1200);
            const effect = fixture.caster.itemTypes.effect.find(e => e.name.startsWith('Spell Effect: Unusual Anatomy'));
            const resist = fixture.caster.system.attributes.resistances.find(r => ['precision', 'critical-hits'].includes(r.type));
            out.effect = effect ? {duration: `${effect.system.duration.value} ${effect.system.duration.unit}`, level: effect.system.level?.value, note: /Retaliate/.test(effect.system.description.value)} : null;
            out.resistance = resist?.value ?? null;
            out.darkvision = fixture.caster.system.perception?.senses?.some?.(sense => sense.type === 'darkvision') ?? null;
            const record = ctx.api.ongoing.records().find(r => r.castId === result.castInstanceId);
            const entry = record?.entries?.find(e => e.metadata?.retaliation);
            const before = foe.hitPoints.value;
            const roll = await ctx.api.ongoing.request('retaliate', {castId: record.castId, uuid: entry.uuid, index: 0, targetUuid: tFoe.uuid}); await wait(800);
            out.hit = {formula: roll?.formula ?? null, total: roll?.total ?? null, lost: before - foe.hitPoints.value};
