            const rec = () => ctx.api.ongoing.records().find(r => r.castId === result.castInstanceId);
            out.sustained = rec().declaration.sustained === true;
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tUndead, tLiving].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(600);
            if (rec().obligations.some(o => o.kind === 'sustain' && o.status === 'pending')) { await ctx.api.ongoing.request('sustain', {castId: result.castInstanceId, revision: rec().revision}); await wait(600); }
            await combat.nextTurn(); await wait(1000); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(1500);
