            const foe = await ctx.actor('lament foe', {level: 1}), foe2 = await ctx.actor('lament foe two', {level: 1}), ally = await ctx.actor('lament ally', {level: 1});
            await foe.update({'system.details.alliance': 'opposition'}); await foe2.update({'system.details.alliance': 'opposition'}); await ally.update({'system.details.alliance': 'party'});
            const tFoe = await place(foe, 2050, 1050), tAlly = await place(ally, 2150, 1050), tFoe2 = await place(foe2, 3300, 1050);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: "PFTEST Lament", shapes: [{type: 'circle', x: 2100, y: 1100, radius: 6 * canvas.grid.size}], color: '#8888aa'}]);
            await wait(600);
