            const fixture = await ctx.setup('Defensive Prescience');
            await fixture.caster.update({'system.details.level.value': 7});
            const plan = await ctx.api.compile(fixture.spell);
            const actors = [await ctx.actor('prescience failure', {level: 1}), await ctx.actor('prescience critical', {level: 1})];
            for (const a of actors) await a.update({'system.attributes.hp.value': 200, 'system.attributes.hp.max': 200});
            const {card} = await ctx.api.saves.start(fixture.spell, {plan, sourceActor: fixture.caster, targets: [await ctx.token(actors[0]), await ctx.token(actors[1])], castRank: 4, dc: 22, skipConfirmation: true});
            for (const [i, degree] of ['failure', 'criticalFailure'].entries()) {
                const t = ctx.state(card).targets.find(x => x.actorUuid === actors[i].uuid);
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            const note = a => a.itemTypes.effect.find(e => (e.system.rules ?? []).some(r => r.key === 'RollTwice'));
            const rule = note(actors[0])?.system.rules.find(r => r.key === 'RollTwice');
            out.notes = actors.map(a => !!note(a));
