            const entry = record?.entries.find(e => e.actorUuid === actors[0].uuid && e.metadata?.triggeredDamage);
            out.results = record?.entries.filter(e => e.metadata?.triggeredDamage).map(e => e.metadata.triggeredDamage.results.join('/'));
