            const target = await ctx.actor('crawl target', {level: 1});
            const {card} = await ctx.api.grantedAction(message, 0, {targets: [await ctx.token(target)], skipConfirmation: true});
            const t = ctx.state(card).targets[0];
            const fresh = () => ctx.state(card).targets.find(x => x.id === t.id);
            if (fresh().confirmation?.status === 'pending') await ctx.api.saves.correctTarget(card, t.id, {action: 'affected', expectedRevision: fresh().revision});
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: 'criticalFailure'});
            await ctx.api.saves.finalize(card); await wait(1500);
