                const actor = await Actor.create({name: `PFTEST P23 Affliction Font ${name}`, type: 'npc', flags: {[NSX]: {phase23AfflictionFixture: true}}, system: {details: {level: {value: 3}, alliance}, attributes: {hp: {value: 50, max: 50}}}});
                actors.push(actor);
