            const card = game.messages.contents.find(m => !before.has(m.id) && m.getFlag(NSX, 'kind') === 'effect-note-area');
            const bonus = actor => { const e = held(actor); const r = e?.system.rules?.find(rule => rule.key === 'FlatModifier'); return r ? Roll.safeEval(String(r.value).replace(/@item\.level/g, e.system.level?.value ?? 0)) : null; };
            out.font = {level: plan.automation.level, held: actors.map(a => !!held(a)), caster: !!held(font.caster), bonus: bonus(actors[0]), button: /pf2e-auto-note-counteract/.test(card?.content ?? '')};
            const counter = card ? await ctx.api.noteCounteract(card, {choice: {name: 'Fear effect', dc: 10, rank: 1}}) : null; await wait(600);
            out.font.countered = counter?.countered ?? null;
            await ctx.api.ongoing.request('end', {castId: result.castInstanceId}); await wait(1500);
            out.font.ended = actors.map(a => !!held(a));
            await font.caster.update({'system.details.level.value': 15}); await font.spell.update({'system.location.heightenedLevel': 8});
            const plan8 = await ctx.api.compile(font.spell);
            const r8 = await ctx.api.execute(font.spell, {sourceActor: font.caster, plan: plan8, castRank: 8, region: await place('Font 8th'), skipConfirmation: true}); await wait(2000);
            out.font.bonus8 = bonus(actors[0]);
