            const foes = await run('Friends to Foes', 7, ['success', 'failure', 'criticalFailure']);
            const [s, f, c] = foes.actors;
            out.foes = {supported: foes.supported, targets: foes.state.targets.length, frightened: foes.actors.map(a => a.getCondition('frightened')?.value ?? 0), confused: c.hasCondition('confused'),
                notes: foes.actors.map(a => notes(a).length)};
            await c.getCondition('frightened')?.delete(); await wait(1500);
            out.foes.confusedAfter = c.hasCondition('confused');
            const dream = await run('Nightmare', 4, ['criticalSuccess', 'criticalFailure'], 4);
            const [cs, cf] = dream.actors;
