            const undead = await Actor.create({name: 'PFTEST P23 Affliction Rip undead', type: 'npc', flags: {[NSX]: {phase23AfflictionFixture: true}}, system: {details: {level: {value: 1}}, traits: {value: ['undead']}}});
            extra.push(undead);
