    // Rank 3 batch 26: the effect stated before the table, its length by the save: Distracting Chatter at 7th (three targets: Off-Guard and the
    // note for 1 round, 3 rounds, 1 minute), Excise Lexicon at 5th (its note for 1 minute, 1 day, unlimited, with the extra word).
    async rank3Batch26(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        const run = async (name, rank, degrees) => {
            const fixture = await ctx.setup(name);
            await fixture.caster.update({'system.details.level.value': rank * 2 - 1}); await fixture.spell.update({'system.location.heightenedLevel': rank});
            const plan = await ctx.api.compile(fixture.spell);
            const actors = []; for (const degree of degrees) actors.push(await ctx.actor(`${name} ${degree}`, {level: 1}));
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: await Promise.all(actors.map(a => ctx.token(a))), castRank: rank, skipConfirmation: true});
            for (const [i, t] of ctx.state(card).targets.entries()) { await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]}); }
            await ctx.api.saves.finalize(card); await wait(1500);
            return {supported: ctx.api.saves.supports(plan), targets: ctx.state(card).targets.length, actors};
        };
        const length = effect => !effect ? null : effect.system.duration.unit === 'unlimited' ? 'unlimited' : `${effect.system.duration.value} ${effect.system.duration.unit}`;
        try {
            const chatter = await run('Distracting Chatter', 7, ['success', 'failure', 'criticalFailure']);
            out.chatter = {supported: chatter.supported, targets: chatter.targets,
                offGuard: chatter.actors.map(a => a.hasCondition('off-guard')),
                notes: chatter.actors.map(a => length(a.itemTypes.effect.find(e => /DC 5 flat check/.test(e.system.description?.value ?? ''))))};
            const excise = await run('Excise Lexicon', 5, ['success', 'failure', 'criticalFailure']);
            const word = actor => actor.itemTypes.effect.find(e => /excised words/.test(e.system.description?.value ?? ''));
            out.excise = {supported: excise.supported, notes: excise.actors.map(a => length(word(a))), extraWord: /one additional word/.test(word(excise.actors[0])?.system.description.value ?? '')};
        } catch (error) { out.error = error.stack ?? error.message; }
        const c = out.chatter ?? {}, e = out.excise ?? {};
        assert(!out.error && c.supported && c.targets === 3 && c.offGuard?.every(Boolean) && c.notes?.join('|') === '1 rounds|3 rounds|1 minutes'
            && e.supported && e.notes?.[0] === '1 minutes' && e.notes?.[1] === '1 days' && e.notes?.[2] === 'unlimited' && e.extraWord, `Rank 3 batch 26: ${JSON.stringify(out)}`);
        return {batch26: out};
    },
    // Rank 3 batch 25: Moonlight Ray: a hit on an unholy creature and a plain one (the same cold roll; the unholy one also takes the extra spirit
