            const plan = await ctx.api.compile(fixture.spell);
            const make = async (name, traits) => { const actor = await Actor.create({name: `PFTEST P23 Affliction ${name}`, type: 'npc', flags: {[NSX]: {phase23AfflictionFixture: true}},
                system: {details: {level: {value: 3}}, traits: {value: traits}, attributes: {hp: {value: 300, max: 300}}}}); extra.push(actor); return actor; };
            const fiend = await make('Moonlight fiend', ['fiend', 'unholy']), plain = await make('Moonlight plain', []), fiend2 = await make('Moonlight fiend crit', ['fiend', 'unholy']);
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: await Promise.all([fiend, plain, fiend2].map(a => ctx.token(a))), castRank: 3, skipConfirmation: true});
            const degrees = ['success', 'success', 'criticalSuccess'];
            for (const [i, t] of ctx.state(card).targets.entries()) { await ctx.api.saves.rollSave(card, t.id, {skipDialog: true, attackNumber: 1}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]}); }
            await ctx.api.saves.finalize(card); await wait(1500);
            const state = ctx.state(card);
