                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: ['failure', 'criticalFailure'][i]});
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true, stage: 'secondary'});
