            const target = await ctx.actor('blizzard target');
            const tTarget = await ctx.token(target);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Howling Blizzard', shapes: [{type: 'circle', x: tTarget.x + 50, y: tTarget.y + 50, radius: 200}], color: '#99ccff'}]);
            const started = await ctx.api.ongoing.startLingering(blizzard.spell, bplan, {castRank: 5, region, dc: 25}); await wait(1500);
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            out.blizzard.terrain = region.behaviors.some(b => b.type === 'modifyMovementCost');
            out.blizzard.initial = rec().obligations.some(o => o.kind === 'membership' || /save/.test(o.key));
            out.blizzard.endsAt = rec().declaration.endsAt;
            await ctx.api.ongoing.request('end', {castId: started.castId}); await wait(1000);
            out.blizzard.regionGone = !canvas.scene.regions.get(region.id);
