            for (const [i, t] of ctx.state(card).targets.entries()) {
                const fresh = () => ctx.state(card).targets.find(x => x.id === t.id);
                if (fresh().confirmation?.status === 'pending') await ctx.api.saves.correctTarget(card, t.id, {action: 'affected', expectedRevision: fresh().revision});
                if (plan.resolution.attackAdjustment) await ctx.api.saves.correctTarget(card, t.id, {action: 'attack-adjustment', degree: '0'});
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]});
            }
