            const card = game.messages.get(rec().obligations.find(x => x.key === `${o.key}:save`).cardId), t = ctx.state(card).targets[0];
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: 'criticalFailure'});
            await ctx.api.saves.finalize(card); await wait(1200);
