            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id); await casterToken.update({x: 1600, y: 700}, {animate: false});
            const tVictim = await place(victim, 2000, 1000);
