            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            out.atCast = rec().obligations.filter(o => o.status === 'pending').length;
            out.note = game.messages.contents.filter(m => !before.has(m.id)).some(m => /running as far away as possible/.test(m.content));
            combat = await Combat.create({scene: canvas.scene.id, active: true});
