            out.save = {formula: state.damage.formula, total: state.damage.total, lost: 500 - victim.hitPoints.value, bleed: bleed ? `${bleed.formula} ${bleed.damageType}` : null};
            const cost = token => { const placeable = token.object; const path = placeable.createTerrainMovementPath([{x: token.x, y: token.y, action: 'walk'}, {x: token.x + 300, y: token.y, action: 'walk'}]); return placeable.measureMovementPath(path)?.cost ?? null; };
            out.terrain = {walkCost: cost(tWalker)};
