            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const casterToken = canvas.scene.tokens.find(t => t.actorId === hyp.caster.id); await casterToken.update({x: 1600, y: 700}, {animate: false});
            const tVictim = await place(victim, 2050, 1050), tSeeker = await place(seeker, 1500, 1000);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Hypnotize', shapes: [{type: 'circle', x: 2100, y: 1100, radius: 150}], color: '#aa66cc'}]);
            await wait(600);
            const plan = await ctx.api.compile(hyp.spell);
            const started = await ctx.api.ongoing.startLingering(hyp.spell, plan, {castRank: 3, region, dc: 24}); await wait(1200);
