            out.gmAction = {added: seek.added.map(uuid => uuid === seeker.uuid ? 'seeker' : 'victim'), refused: seek.refused.map(r => r.reason)};
            const seekObligation = rec().obligations.find(o => o.event === 'gm-action' && o.actorUuid === seeker.uuid);
