        assert(!out.error && out.level === 'automatic' && /at most 3/.test(out.refused ?? '') && s.casters === 3 && JSON.stringify(s.effects) === '[true,true,true,false]'
            && s.duration?.value === 30 && s.duration?.unit === 'days' && JSON.stringify(s.fear) === '["sweetest-solstace-fear:1"]' && s.emotion.length === 0
            && JSON.stringify(cr.effects) === '[true,true]' && JSON.stringify(cr.emotion) === '["sweetest-solstace-emotion:1"]' && cr.fear.length === 1 && cr.winter
            && out.failure.applied === 0 && cf.caster === 4 && cf.helper === 4 && cf.afterReduce === 4 && cf.lockHours === 12 && cf.afterLock === 4 && cf.reducedAfter === 3
            && out.card.degree === 'criticalFailure' && out.card.poison && out.card.cost, `Sweetest Solstice: ${JSON.stringify(out)}`);
