            const cast = await ctx.api.execute(ic.spell, {sourceActor: ic.caster, plan, castRank: 3, skipConfirmation: true, size: {size: 'huge', name: 'Ogre'}, position: {x: 1800, y: 1100}}); await wait(1200);
            const image = await fromUuid(cast.actorUuid), imageToken = await fromUuid(cast.tokenUuid);
            extra.push(image);
            out.image = {dc, ac: image.armorClass.value, reflex: image.saves.reflex.mod, size: image.size, width: imageToken.width, formula: cast.formula};
            const card = game.messages.contents.filter(m => m.getFlag(NSX, 'illusoryCard')?.castId === cast.castInstanceId).at(-1);
            const strike = await ctx.api.illusoryAct(card, {act: 'strike', tokenUuid: tVictim.uuid}); await wait(800);
            const afterHit = victim.hitPoints.value;
            const disbelief = await ctx.api.illusoryAct(card, {act: 'disbelieve', tokenUuid: tVictim.uuid}); await wait(800);
            const afterDisbelief = victim.hitPoints.value;
            const again = await ctx.api.illusoryAct(card, {act: 'strike', tokenUuid: tVictim.uuid}); await wait(800);
            out.combat = {strike, lost: 500 - afterHit, disbelief, recovered: afterDisbelief - afterHit, again, lostAfter: afterDisbelief - victim.hitPoints.value};
            const rec = id => ctx.api.ongoing.records().find(r => r.castId === id);
            await image.saves.reflex.roll({dc: {value: 80}, skipDialog: true});
            // (The end waits behind the queued reconciles: polled, up to 12 seconds.)
