            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const walker = await ctx.actor('surge walker', {level: 1}), swimmer = await ctx.actor('surge swimmer', {level: 1, save: -20}), huge = await ctx.actor('surge huge', {level: 1}), later = await ctx.actor('surge later', {level: 1});
            await huge.update({'system.traits.size.value': 'huge'});
            const tWalker = await place(walker, 2000, 1000), tSwimmer = await place(swimmer, 2100, 1100), tHuge = await place(huge, 2200, 1200), tLater = await place(later, 2200, 1400);
            const plan = await ctx.api.compile(surge.spell);
            const earlier = new Set(game.messages.contents.map(m => m.id));
            const {card} = await ctx.api.saves.start(surge.spell, {sourceActor: surge.caster, plan, targets: [tWalker, tSwimmer, tHuge].map(t => t.object ?? t), castRank: 2, dc: 24, skipConfirmation: true});
            const state = () => ctx.state(card);
