            const tVictim = (await canvas.scene.createEmbeddedDocuments('Token', [{...victim.prototypeToken.toObject(), actorId: victim.id, actorLink: true, x: 2000, y: 1000}]))[0];
            const plan = await ctx.api.compile(spell);
