            const attack = game.messages.contents.find(m => !earlier.has(m.id) && m.flags?.pf2e?.modifiers?.some(mod => mod.label === 'Mythic proficiency'));
            out.one = {hit: r1.hit, formula: r1.formula, up: r1.up, back: r1.back, fallen: r1.fallen, x: tVictim.x, prone: victim.hasCondition('prone'), mythic: attack?.flags.pf2e.modifiers.find(mod => mod.label === 'Mythic proficiency')?.modifier ?? null};
            await victim.decreaseCondition('prone', {forceRemove: true}); await tVictim.update({x: 2000, y: 1000}, {animate: false}); await wait(300);
            const r3 = await ctx.api.execute(spell, {sourceActor: caster, plan, castRank: 4, skipConfirmation: true, targets: [tVictim], actions: 3}); await wait(1200);
            out.three = {hit: r3.hit, formula: r3.formula, up: r3.up, back: r3.back, fallen: r3.fallen, x: tVictim.x};
