        const place = async (actor, squares) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x: 1600 + canvas.grid.size * squares, y: 2000}]))[0];
        const near = await ctx.actor('refrain near ally'); await near.update({'system.details.alliance': 'party'});
