    // Cantrip / rank 1 batch 65: Untamed Shift — PF2e's Effect on the caster, its option chosen by PF2e's prompt from the order feats
    // the caster has (jaws here: a 1d8 piercing unarmed Strike); the level-versus-rank data note and the 2-action GM note.
    async cr1Batch65(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        // A character caster: PF2e builds a Strike rule's attack only for characters.
        const base = await ctx.setup('Untamed Shift');
        const caster = await Actor.create({name: 'PFTEST P23 Affliction untamed character', type: 'character', flags: {[NS]: {[FIXTURE]: true}}, system: {details: {level: {value: 1}}}});
        ctx.saved.actors.push(caster.id); await ctx.persist();
        await canvas.scene.createEmbeddedDocuments('Token', [{...caster.prototypeToken.toObject(), actorId: caster.id, actorLink: true, x: 1800, y: 1600}]);
        const [entry] = await caster.createEmbeddedDocuments('Item', [{name: 'General rules casting', type: 'spellcastingEntry', system: {tradition: {value: 'primal'}, prepared: {value: 'innate'}, spelldc: {dc: 24, value: 14}}}]);
        const spellSource = base.spell.toObject(); delete spellSource._id; spellSource.system.location = {value: entry.id};
        const [spell] = await caster.createEmbeddedDocuments('Item', [spellSource]);
        const fixture = {caster, spell};
        // The order feats PF2e's choice reads (feat:untamed-form, feat:insect-shape), as roll options.
        await fixture.caster.createEmbeddedDocuments('Item', [{name: 'PFTEST order feats', type: 'effect', system: {rules: [
            {key: 'RollOption', option: 'feat:untamed-form'}, {key: 'RollOption', option: 'feat:insect-shape'}], duration: {value: -1, unit: 'unlimited', expiry: null, sustained: false}}}]);
        await wait(300);
        const before = game.messages.contents.length;
        const running = ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan: await ctx.api.compile(fixture.spell), targets: [], castRank: 1, skipConfirmation: true});
        let offered = null;
        for (let i = 0; i < 40; i++) {
            const app = [...foundry.applications.instances.values()].find(x => x.constructor.name === 'PickAThingPrompt');
            const buttons = app ? [...app.element.querySelectorAll('button')] : [];
            const jaws = buttons.find(b => /jaws/i.test(b.textContent));
            if (jaws) { offered = buttons.map(b => b.textContent.trim()).filter(Boolean); jaws.click(); break; }
            await wait(150);
        }
        await running; await wait(1000);
        const effect = fixture.caster.itemTypes.effect.find(e => e.name.startsWith('Spell Effect: Untamed Shift'));
        const strikes = (fixture.caster.system.actions ?? []).map(action => action.slug ?? action.item?.slug ?? action.label);
        const messages = game.messages.contents.slice(before).map(m => (m.content ?? '').replace(/<[^>]+>/g, ' ')).join(' ');
        const out = {offered, selection: effect?.flags?.system?.rulesSelections?.spellEffectUntamedShift ?? null, strikes,
            duration: effect ? `${effect.system.duration.value} ${effect.system.duration.unit}` : null,
            levelNote: /offers its extra choices by your level/.test(messages), actionsNote: /You must cast untamed shift using 2 actions/.test(messages)};
        assert(out.selection === 'untamed-jaws' && strikes.some(slug => /jaws/i.test(slug)) && !strikes.some(slug => /^claw/i.test(slug)) && out.duration === '1 minutes' && !out.levelNote /* the level choices are rank-gated since batch 154 */ && out.actionsNote,
            `Untamed Shift: PF2e's chosen option (jaws) and the notes: ${JSON.stringify(out)}`);
        return out;
    },
    // Cantrip / rank 1 batch 66: Shields of the Spirit — PF2e's Effect on the caster (its granted Raise a Shield; the aura's AC bonus
