        const actors = await Promise.all(['deja success', 'deja failure', 'deja critical failure'].map(name => ctx.actor(name)));
        await ctx.cast(fixture, await Promise.all(actors.map(ctx.token)), ['success', 'failure', 'criticalFailure']); await wait(800);
        const note = actor => actor.itemTypes.effect.find(e => /Déjà Vu/.test(e.name));
