        const foe = await ctx.actor('siphon failure', {level: 3});
        const before = foe.hitPoints.value;
        const card = await ctx.cast(fixture, [await ctx.token(foe)], ['failure']); await wait(1200);
        const state = ctx.state(card);
        const effect = fixture.caster.itemTypes.effect.find(e => e.name === 'Soul Siphon: Temporary Hit Points');
        const text = (game.messages.contents.at(-1)?.content ?? '') + (game.messages.get(card.id)?.content ?? '');
        const out = {damage: state.damage?.total, lost: before - foe.hitPoints.value, drained: foe.getCondition('drained')?.value ?? null,
            temp: fixture.caster.system.attributes.hp.temp, effect: effect ? `${effect.system.duration.value} ${effect.system.duration.unit}` : null,
            card: /Hit Points lost \(damage and Drained\)/.test(text) && /until used/.test(text)};
        assert(out.drained === 1 && out.lost === out.damage + 3 && out.temp === out.lost && out.effect === '-1 unlimited' && out.card,
            `Soul Siphon: temporary HP from the damage and Drained: ${JSON.stringify(out)}`);
