    // Cantrip / rank 1 batch 86: Signal Skyrocket — the GM's yes/no on "If the rocket explodes in an enclosed space …": yes applies
    // the rows (half / full and Dazzled / double and Blinded); no leaves every creature unaffected. The placement rule is a note.
    async cr1Batch86(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const fixture = await ctx.setup('Signal Skyrocket');
        const plan = await ctx.api.compile(fixture.spell);
        const run = async (names, degrees, answer) => {
            const actors = await Promise.all(names.map(name => ctx.actor(name)));
            const before = actors.map(a => a.hitPoints.value);
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: await Promise.all(actors.map(ctx.token)), castRank: 1, dc: 24, skipConfirmation: true});
            let refused = null;
            try { await ctx.api.saves.finalize(card); } catch (error) { refused = error.message; }
            for (const [index, target] of ctx.state(card).targets.entries()) {
                await ctx.api.saves.rollSave(card, target.id, {skipDialog: true});
                await ctx.api.saves.correctTarget(card, target.id, {action: 'degree', degree: degrees[index]});
            }
            await ctx.api.saves.answerCastGate(card, answer);
            await ctx.api.saves.finalize(card); await wait(1000);
            const state = ctx.state(card);
            const text = (game.messages.get(card.id)?.content ?? '').replace(/<[^>]+>/g, ' ');
            return {refusedBeforeAnswer: /Does this hold/.test(refused ?? ''), total: state.damage?.total ?? null, lost: actors.map((a, i) => before[i] - a.hitPoints.value),
                conditions: actors.map(a => ['dazzled', 'blinded'].filter(slug => a.hasCondition(slug))), placement: /can't change the direction or distance/.test(text)};
        };
        const out = {yes: await run(['rocket success', 'rocket failure', 'rocket critical'], ['success', 'failure', 'criticalFailure'], 'yes')};
        out.no = await run(['rocket open failure'], ['failure'], 'no');
        const y = out.yes;
        assert(y.refusedBeforeAnswer && y.lost[0] === Math.floor(y.total / 2) && y.lost[1] === y.total && y.lost[2] === y.total * 2
            && JSON.stringify(y.conditions) === '[[],["dazzled"],["blinded"]]' && y.placement
            && out.no.refusedBeforeAnswer && JSON.stringify(out.no.lost) === '[0]' && JSON.stringify(out.no.conditions) === '[[]]',
            `Signal Skyrocket: the GM's answer gates the explosion: ${JSON.stringify(out)}`);
        return out;
    },
