            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            await ctx.api.ongoing.request('sustain', {castId: cast.castInstanceId, revision: rec().revision}); await wait(1200);
            h2 = hp();
            // A second Sustain the same round: no pulse.
