                await ctx.api.saves.rollSave(card, target.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, target.id, {action: 'degree', degree: degrees[ours[o.actorUuid]]});
                await ctx.api.saves.finalize(card); await wait(1000);
