        const tBurn = await place(burner, 10 * g, 8 * g), tWalk = await place(walker, 16 * g, 8 * g);
        await wait(800);
        const [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Wildfire area', shapes: [{type: 'circle', x: 10.5 * g, y: 8.5 * g, radius: 2 * g}], color: '#dd4411'}]);
        const plan = await ctx.api.compile(fixture.spell);
        const started = await ctx.api.ongoing.startLingering(fixture.spell, plan, {castRank: 3, region, dc: 24});
        const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
        const ours = {[burner.uuid]: 'burner', [walker.uuid]: 'walker'};
        const resolve = async degrees => {
            for (const o of rec().obligations.filter(o => o.kind === 'membership' && o.status === 'pending')) {
                const mine = o.actorUuid in ours && ours[o.actorUuid] in degrees;
                await ctx.api.ongoing.request('review-targets', {castId: started.castId, revision: rec().revision, key: o.key, affected: mine}); await wait(800);
                if (!mine) continue;
                const card = game.messages.get(rec().obligations.find(x => x.key === `${o.key}:save`).cardId), target = ctx.state(card).targets[0];
                await ctx.api.saves.rollSave(card, target.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, target.id, {action: 'degree', degree: degrees[ours[o.actorUuid]]});
                await ctx.api.saves.finalize(card); await wait(1000);
            }
        };
        const out = {initial: rec().obligations.filter(o => o.kind === 'membership').length};
        // The walker moves 3 squares into the area: 3 × 2 fire.
        const before = walker.hitPoints.value;
        const hazard = await ctx.api.ongoing.request('hazard-move', {castId: started.castId, revision: rec().revision, tokenUuid: tWalk.uuid, squares: 3}); await wait(800);
        out.hazard = {amount: hazard.amount, squares: hazard.squares, lost: before - walker.hitPoints.value};
        const combat = await Combat.create({scene: canvas.scene.id, active: true});
        try {
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tBurn].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 40 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
            const radius = () => Math.round(canvas.scene.regions.get(region.id).shapes[0].radius / g * 5);
            out.radiusBefore = radius();
            await ctx.api.ongoing.request('sustain', {castId: started.castId, revision: rec().revision}); await wait(800);
            out.radiusAfter = radius(); out.areaValue = rec().declaration.area.value;
            await combat.nextTurn(); await wait(1000); await ctx.api.ongoing.reconcile({clockEvent: true});
            await combat.nextTurn(); await wait(1200); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(400);
            out.turnEnd = rec().obligations.filter(o => o.kind === 'membership' && o.status === 'pending' && o.actorUuid === burner.uuid).map(o => o.event);
            await resolve({burner: 'failure'});
            out.persistent = burner.itemTypes.condition.filter(c => c.slug === 'persistent-damage').map(c => `${c.system.persistent?.formula} ${c.system.persistent?.damageType}`);
        } finally { await combat.delete(); }
        await ctx.api.ongoing.request('end', {castId: started.castId}); await wait(800);
        await region.delete().catch(() => null);
        assert(out.initial === 0 && out.hazard.amount === 2 && out.hazard.lost === 6 && out.radiusBefore === 10 && out.radiusAfter === 15 && out.areaValue === 15
            && JSON.stringify(out.turnEnd) === '["turn-end"]' && JSON.stringify(out.persistent) === '["2 fire"]', `Wildfire: ${JSON.stringify(out)}`);
        for (const t of [tBurn, tWalk]) await t.delete().catch(() => null);
