        await ally.update({'system.details.alliance': 'party'});
        const [tThrall, tVictim, tAlly] = await Promise.all([thrall, victim, ally].map(ctx.token));
        const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
