              await foe.applyDamage({damage: dmg.rolls[0], token: tFoe, rollOptions: new Set(dmg.flags.pf2e.context.options ?? []), skipIWR: false}); await wait(1500);
              return {total: dmg.rolls[0].total, lost: hp - foe.hitPoints.value};
