        const caster = fixture.caster;
        const [burned, spared] = await Promise.all(['pyro burned', 'pyro spared'].map(name => ctx.actor(name, {level: 1})));
        const tokens = await Promise.all([burned, spared].map(ctx.token));
        const plan = await ctx.api.compile(fixture.spell);
        const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: caster, plan, targets: tokens, castRank: 1, dc: 24, skipConfirmation: true});
        for (const [index, degree] of ['failure', 'criticalSuccess'].entries()) {
            const t = ctx.state(card).targets[index];
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
        }
        await ctx.api.saves.finalize(card); await wait(1800);
        const markOn = actor => actor.itemTypes.effect.some(e => e.name === 'Pyroclastic Truth: marked by fire');
        const persistent = actor => actor.itemTypes.condition.filter(c => c.slug === 'persistent-damage').map(c => `${c.system.persistent?.formula} ${c.system.persistent?.damageType}`);
        const state = ctx.state(card);
