        const lethologic = caster.itemTypes.effect.find(e => e.name === 'Lethologic Mark (Pyroclastic Truth)');
        out.lethologic = {present: !!lethologic, healNote: /atone ritual/.test(lethologic?.system.description.value ?? '')};
        await ctx.api.ongoing.request('fuel', {castId: out.castId}); await wait(1500);
