        await caster.applyDamage({damage: await new DamageRoll('3[fire]').evaluate(), token: casterToken, rollOptions: new Set(['fire', 'item:damage:type:fire']), skipIWR: false}); await wait(1500);
        out.frightened = caster.getCondition?.('frightened')?.value ?? 0;
