                await combat.createEmbeddedDocuments('Combatant', [casterToken, tAlly, tEnemy, tFar].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 40 - i * 10})));
                await combat.startCombat(); await wait(700); await ctx.api.ongoing.reconcile({clockEvent: true});
