                out.cover = {ally: ally.itemTypes.effect.some(e => /Cover/.test(e.name)), enemy: enemy.itemTypes.effect.some(e => /Cover/.test(e.name))};
                if (tradition === 'primal') {
                    const dc = effectOn(enemy)?.flags?.[NSP]?.outcomeEffect?.escape?.dc;
                    const roll = await new Roll(`${dc}`).evaluate();
                    const before = new Set(game.messages.contents.map(m => m.id));
                    const check = await ChatMessage.create({speaker: ChatMessage.getSpeaker({actor: enemy}), rolls: [roll], content: 'PFTEST scripted Escape',
                        flags: {pf2e: {context: {type: 'skill-check', options: ['action:escape', 'action:escape:athletics'], origin: {actor: enemy.uuid}, isReroll: false}}}});
                    await wait(900);
                    const card = game.messages.contents.find(c => !before.has(c.id) && c.flags?.[NSP]?.escapeTermination?.checkMessageId === check.id);
                    if (card) await ctx.api.escape.end(card, card.flags[NSP].escapeTermination.entries[0].id);
                    await wait(900); out.afterEscape = !!effectOn(enemy);
                }
