        assert(p.recordActive && p.aura && p.effects.ally?.selection === 'primal' && p.effects.enemy?.selection === 'primal' && p.effects.enemy.escape && p.effects.caster?.selection === 'primal' && !p.effects.far && p.afterEscape === false
            && o.effects.ally?.selection === 'occult' && !o.effects.enemy && o.cover.ally && !o.cover.enemy, `Manifest Will: ${JSON.stringify(out)}`);
