            let refusedSteel = null; try { await ctx.api.execute(mend.spell, {sourceActor: mend.caster, plan: await ctx.api.compile(mend.spell), targets: [tO], castRank: 1, itemId: steel.id, skipConfirmation: true}); } catch (e) { refusedSteel = e.message; }
            out.mending.steelRank1Refused = /can't be mended/.test(refusedSteel ?? '');
