    // Cantrip / rank 1 batch 41: Halcyon Mists — PF2e's Effect (TempHP from its rolled badge, Concealed), one persistent
    // damage of the listed types ended (the caster chooses among several), and the no-Hide reminder.
    async cr1Batch41(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const persistent = (type, formula) => ({name: `Persistent ${type}`, type: 'condition', system: {slug: 'persistent-damage', persistent: {formula, damageType: type, dc: 15}}});
        const cast = async (actor) => {
            const fixture = await ctx.setup('Halcyon Mists');
            const plan = await ctx.api.compile(fixture.spell);
            const before = game.messages.contents.length;
            await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(actor)], castRank: 1, skipConfirmation: true});
            await wait(1200);
            return game.messages.contents.slice(before).map(m => m.content ?? '').join(' ');
        };
        const one = await ctx.actor('halcyon one'), two = await ctx.actor('halcyon two');
        const oneSource = persistent('fire', '1d6'); await one.createEmbeddedDocuments('Item', [oneSource]);
        await two.createEmbeddedDocuments('Item', [persistent('fire', '1d6'), persistent('acid', '1d4')]);
        await wait(500);
        const kinds = a => a.itemTypes.condition.filter(c => c.slug === 'persistent-damage').map(c => c.system.persistent?.damageType).sort();
        const beforeOne = kinds(one), beforeTwo = kinds(two);
        const oneText = await cast(one);
        const twoText = await cast(two);
        const effect = a => a.itemTypes.effect.find(e => e.name.startsWith('Spell Effect: Halcyon Mists'));
        const out = {one: {before: beforeOne, after: kinds(one), temp: one.system.attributes.hp.temp, concealed: one.hasCondition('concealed'), effect: !!effect(one), ended: /ended Persistent/.test(oneText)},
            two: {before: beforeTwo, after: kinds(two), choose: /choose one to end/.test(twoText), temp: two.system.attributes.hp.temp},
            hideNote: /can't be used to Hide/.test(oneText)};
        assert(JSON.stringify(out.one.before) === '["fire"]' && out.one.after.length === 0 && out.one.ended && out.one.temp >= 1 && out.one.temp <= 8 && out.one.concealed && out.one.effect
            && JSON.stringify(out.two.after) === '["acid","fire"]' && out.two.choose && out.two.temp >= 1 && out.hideNote,
            `Halcyon Mists: temp HP, persistent ended or chosen, reminder: ${JSON.stringify(out)}`);
        return {halcyonMists: out};
    },
