            club: {potency: clubNow.system.runes.potency, versatileFire: clubNow.system.traits.value.includes('versatile-fire'), dice: (synth.damageDice[`${club.id}-damage`] ?? []).length},
            sword: {potency: swordNow.system.runes.potency, versatileFire: swordNow.system.traits.value.includes('versatile-fire'), dice: (synth.damageDice[`${sword.id}-damage`] ?? []).length},
            toggle: fixture.caster.rules.some(r => r.key === 'RollOption' && r.option === 'dismiss-funeral-flames'),
