        assert(out.selection && out.club.potency === 1 && out.club.versatileFire && out.club.dice >= 1 && out.sword.potency === 0 && !out.sword.versatileFire && out.sword.dice === 0
            && out.toggle && out.light && !out.note /* the text is automated (ruleOverrides) since batch 152: no data note */, `Funeral Flames: the club's Effect and the data note: ${JSON.stringify(out)}`);
        return {funeralFlames: out};
