        const flavor = game.messages.contents.filter(m => m.flags?.['pf2e-automatic-resolution']?.kind === 'direct-damage').at(-1)?.flavor ?? '';
        const out = {forceFang: {total: r.damage?.total, lost: 500 - foe.hitPoints.value, reach: /melee reach/.test(flavor), spellstrike: /Spellstrike/.test(flavor)}};
