        const l = out.lifeLink;
        assert(l.healed === l.healTotal && l.healed >= 1 && l.healed <= 4 && l.moved === 3 && l.after[0] === l.before[0] - 3 && l.after[1] === l.before[1] + 3 && /already shared this round/.test(l.again ?? ''),
            `Life Link: 1d4 healing, 3 of the damage moved to the caster, once a round: ${JSON.stringify(l)}`);
