            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: await Promise.all(actors.map(a => ctx.token(a))), castRank, dc: 24, skipConfirmation: true});
            for (const [i, t] of ctx.state(card).targets.entries()) {
                if (confirm) { await ctx.api.saves.correctTarget(card, t.id, {action: confirm[i], expectedRevision: t.revision}); await wait(300); }
                const fresh = ctx.state(card).targets[i];
                if (fresh.eligible === false || fresh.confirmation?.status === 'unaffected') continue;
                if (answers) await ctx.api.saves.correctTarget(card, t.id, {action: 'attack-adjustment', degree: String(answers[i])});
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]});
            }
